                      'class TestStoreDecodeRoundTrip:\n'
                      '    """End-to-end: store KV into TQ cache, decode, compare with '
                      'references."""\n'
                      '\n'
                      '    def '
                      'test_qwen38_k8v4_bf16_gqa_matches_packed_reference(self):\n'
                      '        """Exercise Qwen3.8\'s actual K8V4 dimensions and '
                      'numeric path.\n'
                      '\n'
                      '        This deliberately uses multiple cache blocks and '
                      'nontrivial attention.\n'
                      '        Unlike a one-token test, it independently verifies '
                      'every stored byte,\n'
                      '        GQA head mapping, score softmax, and value '
                      'accumulation.  It also uses\n'
                      '        BF16 inputs, D=256, 24 query heads, and 4 KV heads: the '
                      'exact full-\n'
                      '        attention geometry of Qwen3.8-27B.\n'
                      '        """\n'
                      '        from vllm.v1.attention.ops.triton_turboquant_decode '
                      'import (\n'
                      '            triton_turboquant_decode_attention,\n'
                      '        )\n'
                      '        from vllm.v1.attention.ops.triton_turboquant_store '
                      'import (\n'
                      '            triton_turboquant_store,\n'
                      '        )\n'
                      '\n'
                      '        preset = "turboquant_k8v4"\n'
                      '        d = 256\n'
                      '        num_kv_heads = 4\n'
                      '        num_query_heads = 24\n'
                      '        num_tokens = 37\n'
                      '        block_size = 16\n'
                      '        num_blocks = math.ceil(num_tokens / block_size)\n'
                      '        device = torch.device(DEVICE_TYPE)\n'
                      '        cfg = TurboQuantConfig.from_cache_dtype(preset, '
                      'head_dim=d)\n'
                      '\n'
                      '        assert cfg.key_packed_size == 256\n'
                      '        assert cfg.value_packed_size == 132\n'
                      '        assert cfg.slot_size == 388\n'
                      '        assert cfg.slot_size_aligned == 388\n'
                      '\n'
                      '        torch.manual_seed(38027)\n'
                      '        key = torch.randn(\n'
                      '            num_tokens,\n'
                      '            num_kv_heads,\n'
                      '            d,\n'
                      '            device=device,\n'
                      '            dtype=torch.bfloat16,\n'
