                      '\n'
                      '        kv_cache = torch.zeros(\n'
                      '            num_blocks,\n'
                      '            block_size,\n'
                      '            num_kv_heads,\n'
                      '            cfg.slot_size_aligned,\n'
                      '            device=device,\n'
                      '            dtype=torch.uint8,\n'
                      '        )\n'
                      '        slot_mapping = torch.arange(num_tokens, device=device, '
                      'dtype=torch.int32)\n'
                      '        # K8 does not use the rotation/centroid tables, but the '
                      'common launcher\n'
                      '        # contract still requires valid tensors.\n'
                      '        identity = torch.eye(d, device=device, '
                      'dtype=torch.float32)\n'
                      '        centroids = torch.arange(16, device=device, '
                      'dtype=torch.float32)\n'
                      '        midpoints = torch.arange(15, device=device, '
                      'dtype=torch.float32) + 0.5\n'
                      '\n'
                      '        triton_turboquant_store(\n'
                      '            key,\n'
                      '            value,\n'
                      '            kv_cache,\n'
                      '            slot_mapping,\n'
                      '            identity,\n'
                      '            midpoints,\n'
                      '            mse_bits=cfg.key_mse_bits,\n'
