                      '        actual_codes = actual_codes_cpu.to(device)\n'
                      '        rounded_inputs = (\n'
                      '            (value_fp32 - value_min.unsqueeze(-1)) / '
                      'quant_scale.unsqueeze(-1) + 0.5\n'
                      '        )\n'
                      '        boundary_distance = (rounded_inputs - '
                      'rounded_inputs.round()).abs()\n'
                      '        code_delta = (actual_codes - value_codes).abs()\n'
                      '        stable = boundary_distance > 2e-5\n'
                      '        assert (code_delta[stable] == 0).all()\n'
                      '        assert (code_delta[~stable] <= 1).all()\n'
                      '\n'
                      '        block_table = torch.arange(\n'
                      '            num_blocks, device=device, dtype=torch.int32\n'
                      '        ).unsqueeze(0)\n'
                      '        seq_lens = torch.tensor([num_tokens], device=device, '
                      'dtype=torch.int32)\n'
                      '        output = triton_turboquant_decode_attention(\n'
                      '            query=query,\n'
                      '            kv_cache=kv_cache,\n'
                      '            block_table=block_table,\n'
                      '            seq_lens=seq_lens,\n'
                      '            Pi=identity,\n'
                      '            centroids=centroids,\n'
                      '            scale=1.0 / math.sqrt(d),\n'
                      '            mse_bits=cfg.key_mse_bits,\n'
                      '            key_packed_size=cfg.key_packed_size,\n'
                      '            value_quant_bits=cfg.effective_value_quant_bits,\n'
                      '            key_fp8=True,\n'
                      '            norm_correction=False,\n'
                      '            PiT=identity,\n'
                      '            max_num_kv_splits=4,\n'
                      '        )\n'
                      '\n'
                      '        dequant_key = key_fp8.float()\n'
                      '        dequant_value = (\n'
                      '            actual_codes.float() * '
