                      '    if request_cls is BatchChatCompletionRequest:\n'
                      '        return {"model": "m", "messages": [[{"role": "user", '
                      '"content": "hi"}]]}\n'
                      '    if issubclass(request_cls, CompletionRequest):\n'
                      '        return {"model": "m", "prompt": "hi"}\n'
                      '    if request_cls is ResponsesRequest:\n'
                      '        return {"model": "m", "input": "hi"}\n'
                      '    if request_cls in (AnthropicMessagesRequest, '
                      'AnthropicCountTokensRequest):\n'
                      '        return {\n'
                      '            "model": "m",\n'
                      '            "max_tokens": 16,\n'
                      '            "messages": [{"role": "user", "content": "hi"}],\n'
                      '        }\n'
                      '    if issubclass(request_cls, GenerateRequest):\n'
                      '        return {\n'
                      '            "request_id": "req-1",\n'
                      '            "token_ids": [1, 2, 3],\n'
