                      'def _body_schema(schema: dict, path: str) -> dict:\n'
                      '    content = '
                      'schema["paths"][path]["post"]["requestBody"]["content"]\n'
                      '    ref = content["application/json"]["schema"]\n'
                      '    if "$ref" not in ref:\n'
                      '        ref = next(item for item in ref.get("anyOf", ()) if '
                      '"$ref" in item)\n'
                      '    return '
                      'schema["components"]["schemas"][ref["$ref"].rsplit("/", 1)[1]]\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize(\n'
                      '    "path",\n'
                      '    [\n'
                      '        "/v1/chat/completions",\n'
                      '        "/v1/chat/completions/batch",\n'
                      '        "/v1/completions",\n'
                      '        "/v1/responses",\n'
