                      ')\n'
                      'def '
                      'test_the_served_schema_requires_the_scope_on_generation(path):\n'
                      '    body = _body_schema(_app().openapi(), path)\n'
                      '    assert "kv_scope" in body["required"], (path, '
                      'body.get("required"))\n'
                      '\n'
                      '\n'
