                      '    schema = _app().openapi()\n'
                      '    body = _body_schema(schema, path)\n'
                      '    assert "kv_scope" not in body["properties"], path\n'
                      '    # What a render returns is a token request that still has '
                      'to name its\n'
                      '    # line of work before it can be generated.\n'
                      '    rendered = '
                      'schema["components"]["schemas"]["GenerateRequest"]\n'
                      '    assert "kv_scope" not in rendered["properties"]\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("scope", ["a", "unrelated ID", "α / '
                      'β", " leading-and-trailing "])\n'
                      '@pytest.mark.parametrize("request_cls", _SAMPLING_SURFACES)\n'
                      'def '
