                      '    assert errors == [(["changed"], 2)] and preprocessed == []\n'
                      '\n'
                      '    request.sampling_params = SamplingParams(max_tokens=1, '
                      'extra_args={"kv_scope": "a"})\n'
                      '    received = EngineCoreProc._receive_add_request(\n'
                      '        engine, decoder, MsgpackEncoder().encode(request)\n'
                      '    )\n'
                      '    assert received[0].request_id == "changed" and len(errors) '
                      '== 1\n'
                      '\n'
                      '\n'
