                      '        GroupOffloadConfig(0, 128, 128, 8, None, None),\n'
                      '        GroupOffloadConfig(1, 16, 16, 1, None, 1, '
                      'is_recurrent=True),\n'
                      '    )\n'
                      '    config = SchedulerOffloadConfig(groups, 1, 16, 1, True, '
                      'False)\n'
                      '    request = SimpleNamespace(\n'
                      '        kv_transfer_params=None, num_prompt_tokens=160, '
                      'num_tokens=160,\n'
                      '    )\n'
                      '    state = RequestOffloadState(config, request, '
                      'ReqContext("r", kv_scope="a"),\n'
                      '                               RequestOffloadingContext())\n'
                      '    state.group_states[0].offload_keys[:] = to_keys([100])\n'
                      '    state.group_states[0].block_ids[:] = [1]\n'
                      '    state.group_states[1].offload_keys[:] = '
                      'to_keys(list(range(10)))\n'
                      '    state.group_states[1].block_ids[:] = list(range(1, 11))\n'
                      '    for group in state.group_states:\n'
                      '        state.req_context.prefix_content.update({key: (key,) '
                      'for key in group.offload_keys})\n'
                      '    scheduler = '
                      'OffloadingConnectorScheduler.__new__(OffloadingConnectorScheduler)\n'
                      '    scheduler.config = config\n'
                      '    scheduler.manager = MagicMock(spec=OffloadingManager)\n'
                      '    keys = scheduler._retain_context(state, 160)\n'
                      '    assert keys == set(to_keys([100, 7]))\n'
                      '    scheduler.manager.retain_context.assert_called_once_with(\n'
                      '        to_keys([100, 7]), state.req_context,\n'
                      '    )\n'
                      '\n'
