                      'def _coalesced_window_cache():\n'
                      '    """CPU chunk 0 has an unwritten leading SWA block at the '
                      '96-token frontier."""\n'
                      '    from vllm.v1.kv_cache_interface import KVCacheConfig\n'
                      '    from vllm.v1.kv_offload.cpu.manager import '
                      'CPUOffloadingManager\n'
                      '\n'
                      '    config = '
                      "_make_vllm_config(extra_config={'blocks_per_chunk': 3})\n"
                      '    groups = [\n'
                      "        KVCacheGroupSpec(['full'], FullAttentionSpec(\n"
                      '            block_size=16, num_kv_heads=1, head_size=1, '
                      'dtype=torch.float32,\n'
                      '        )),\n'
                      "        KVCacheGroupSpec(['window'], SlidingWindowSpec(\n"
                      '            block_size=16, num_kv_heads=1, head_size=1, '
                      'dtype=torch.float32,\n'
                      '            sliding_window=80,\n'
                      '        )),\n'
                      '    ]\n'
                      '    kv_config = KVCacheConfig(num_blocks=20, '
                      'kv_cache_tensors=[], kv_cache_groups=groups)\n'
                      '    spec = MockOffloadingSpec(build_offloading_config(config, '
                      'kv_config))\n'
                      '    scheduler = OffloadingConnectorScheduler(spec, config, '
                      'kv_config)\n'
                      '    scheduler.manager = CPUOffloadingManager(8)\n'
                      '\n'
                      '    def request(agent, size):\n'
                      '        req = MagicMock()\n'
                      '        req.request_id = agent\n'
                      '        req.kv_scope = agent\n'
                      '        req.kv_transfer_params = None\n'
                      '        req.num_prompt_tokens = size\n'
                      '        req.num_tokens = size\n'
                      '        req.num_computed_tokens = 0\n'
                      "        req.block_hashes = [BlockHash(f'window-h{i}'.encode()) "
                      'for i in range(size // 16)]\n'
                      '        req.all_token_ids = list(range(size))\n'
                      '        req.is_finished.return_value = False\n'
                      '        req.skip_reading_prefix_cache = False\n'
                      '        req.lora_request = None\n'
                      '        scheduler.on_new_request(req)\n'
                      '        return req\n'
                      '\n'
                      "    writer = request('writer', 97)\n"
                      '    state = scheduler._req_status[writer.request_id]\n'
                      '    state.update_offload_keys()\n'
                      '    state.group_states[0].block_ids[:] = [1, 2, 3, 4, 5, 6]\n'
                      '    state.group_states[1].block_ids[:] = [0, 12, 13, 14, 15, '
                      '16]\n'
                      '    scheduler._build_store_jobs(SimpleNamespace(\n'
                      '        num_scheduled_tokens={writer.request_id: 96}, '
                      'finished_req_ids=(),\n'
                      '    ))\n'
                      '    for job in scheduler._jobs.values():\n'
                      '        scheduler.manager.complete_store(job.keys, '
                      'state.req_context)\n'
                      '    scheduler.manager.on_request_finished(state.req_context)\n'
                      '    return scheduler, writer, request\n'
                      '\n'
                      '\n'
                      'def '
                      'test_coalesced_window_holds_only_gpu_data_that_was_written():\n'
                      '    scheduler, writer, _ = _coalesced_window_cache()\n'
                      '    first_chunk = make_offload_key(writer.block_hashes[2], 1)\n'
                      '    available = '
                      'scheduler.manager._available_content[first_chunk]\n'
                      '    assert available == tuple(\n'
                      '        make_offload_key(block_hash, 1) for block_hash in '
                      'writer.block_hashes[1:3]\n'
                      '    )\n'
                      '    assert first_chunk not in '
                      'scheduler.manager._complete_blocks\n'
                      '\n'
                      '\n'
                      'def '
                      'test_coalesced_window_reuses_its_frontier_without_claiming_an_earlier_window():\n'
                      '    scheduler, _, request = _coalesced_window_cache()\n'
                      "    same_frontier = request('same-frontier', 97)\n"
                      '    assert scheduler.get_num_new_matched_tokens(same_frontier, '
                      '0) == (96, True)\n'
                      "    earlier_frontier = request('earlier-frontier', 49)\n"
                      '    # A shorter request needs the SWA data at tokens 0..16. The '
                      'earlier\n'
                      '    # frontier is unavailable even though its chunk-end hash is '
                      'resident.\n'
                      '    assert '
                      'scheduler.get_num_new_matched_tokens(earlier_frontier, 0) == '
                      '(0, False)\n'
                      '\n'
