                       'def test_cpu_eviction_removed_precedes_stored():\n'
                       '    """An eviction is announced before the store that reuses '
                       'its capacity."""\n'
                       '    manager = make_cpu_manager(num_blocks=2, '
                       'enable_events=True)\n'
                       '\n'
                       '    manager.prepare_store(to_keys([1, 2]), _EMPTY_REQ_CTX)\n'
                       '    manager.complete_store(to_keys([1, 2]), _EMPTY_REQ_CTX)\n'
                       '    list(manager.take_events())\n'
                       '\n'
                       '    manager.prepare_store(to_keys([3]), _EMPTY_REQ_CTX)\n'
                       '    manager.complete_store(to_keys([3]), _EMPTY_REQ_CTX)\n'
                       '\n'
                       '    events = list(manager.take_events())\n'
                       '    removed_idx = [i for i, event in enumerate(events) if '
                       'event.removed]\n'
                       '    stored_idx = [i for i, event in enumerate(events) if not '
                       'event.removed]\n'
                       '    assert removed_idx and stored_idx, events\n'
                       '    assert max(removed_idx) < min(stored_idx)\n'
                       '    assert all(event.medium == manager.medium for event in '
                       'events)\n'
