                      "    a, b, c = map(context, ['writer', 'fork', 'incoming'])\n"
                      "    store(m, a, [b'prefix', b'a'])\n"
                      "    if reuse == 'retain':\n"
                      "        m.retain_context([b'prefix'], b)  # includes GPU "
                      'prefix-cache hits\n'
                      "    elif reuse == 'load':\n"
                      "        load(m, [b'prefix'], b)\n"
                      "        m.complete_load([b'prefix'], b)\n"
                      '    else:\n'
