                      "@pytest.mark.parametrize('seed', range(12))\n"
                      'def test_shared_retention_randomized_capacity_pressure(seed):\n'
                      '    rng = random.Random(seed)\n'
                      '    m = CPUOffloadingManager(17)\n'
                      '    contexts = [context(str(i)) for i in range(7)]\n'
                      '    for _ in range(200):\n'
                      '        ctx = rng.choice(contexts)\n'
                      '        keys = {bytes([k]) for k in rng.sample(range(30), '
                      'rng.randint(1, 8))}\n'
                      '        m.retain_context(keys, ctx)\n'
                      '        survivors = {\n'
                      '            req_id: set(c.keys) for req_id, c in '
                      'm._contexts.items()\n'
                      '            if c.keys <= m._blocks.keys()\n'
                      '        }\n'
                      '        result = m.prepare_store(keys, ctx)\n'
                      '        if result is not None:\n'
                      '            m.complete_store(result.keys_to_store, ctx)\n'
                      '        for req_id, required in survivors.items():\n'
                      '            if req_id in m._contexts:\n'
                      '                assert required <= m._blocks.keys()\n'
                      '        if rng.random() < 0.3:\n'
                      '            m.on_request_finished(ctx)\n'
                      '        check(m)\n'
