                             '\n'
                             '\n'
                             'def '
                             'test_transfer_metrics_count_shared_reads_once_and_clear_histograms():\n'
                             '    m = CPUOffloadingManager(4)\n'
                             "    writer, fork = context('writer'), context('fork')\n"
                             "    pending = store(m, writer, [b'a', b'b'], "
                             'complete=False)\n'
                             '    stats = m.get_stats().reduce()\n'
                             '    assert '
                             'stats[CPUOffloadingMetrics.CPU_CACHE_USAGE_PERC] == 0.5\n'
                             '    assert '
                             'stats[CPUOffloadingMetrics.CPU_CACHE_WRITE_USAGE_PERC] '
                             '== 0.5\n'
                             '    assert '
                             'stats[CPUOffloadingMetrics.CPU_CACHE_READ_USAGE_PERC] == '
                             '0.0\n'
                             '    assert '
                             "stats[f'{CPUOffloadingMetrics.CPU_ALLOCATION_SIZE}_count'] "
                             '== 1\n'
                             '    assert '
                             "stats[f'{CPUOffloadingMetrics.CPU_ALLOCATION_SIZE}_sum'] "
                             '== 2\n'
                             '    m.complete_store(pending.keys_to_store, writer)\n'
                             "    load(m, [b'a'], writer)\n"
                             "    load(m, [b'a'], fork)\n"
                             '    stats = m.get_stats().reduce()\n'
                             '    assert '
                             'stats[CPUOffloadingMetrics.CPU_CACHE_USAGE_PERC] == '
                             '0.25\n'
                             '    assert '
                             'stats[CPUOffloadingMetrics.CPU_CACHE_WRITE_USAGE_PERC] '
                             '== 0.0\n'
                             '    assert '
                             'stats[CPUOffloadingMetrics.CPU_CACHE_READ_USAGE_PERC] == '
                             '0.25\n'
                             '    assert '
                             "f'{CPUOffloadingMetrics.CPU_ALLOCATION_SIZE}_count' not "
                             'in stats\n'
                             "    m.complete_load([b'a'], writer)\n"
                             '    assert '
                             'm.get_stats().reduce()[CPUOffloadingMetrics.CPU_CACHE_READ_USAGE_PERC] '
                             '== 0.25\n'
                             "    m.complete_load([b'a'], fork)\n"
                             '    assert '
                             'm.get_stats().reduce()[CPUOffloadingMetrics.CPU_CACHE_USAGE_PERC] '
                             '== 0.0\n'
                             '\n'
                             '\n'
                             'def '
                             'test_allocation_pressure_and_zero_capacity_have_defined_metrics():\n'
                             '    empty = '
                             'CPUOffloadingManager(0).get_stats().reduce()\n'
                             '    assert '
                             'empty[CPUOffloadingMetrics.CPU_CACHE_USAGE_PERC] == 0.0\n'
                             '    assert '
                             'empty[CPUOffloadingMetrics.CPU_CACHE_WRITE_USAGE_PERC] '
                             '== 0.0\n'
                             '    assert '
                             'empty[CPUOffloadingMetrics.CPU_CACHE_READ_USAGE_PERC] == '
                             '0.0\n'
                             '    m = CPUOffloadingManager(1)\n'
                             "    store(m, context('writer'), [b'a'], complete=False)\n"
                             '    m.get_stats()\n'
                             "    assert m.prepare_store([b'b'], context('next')) is "
                             'None\n'
                             '    stats = m.get_stats().reduce()\n'
                             '    assert '
                             "stats[f'{CPUOffloadingMetrics.CPU_ALLOCATION_SIZE}_count'] "
                             '== 1\n'
                             '    assert '
                             "stats[f'{CPUOffloadingMetrics.CPU_ALLOCATION_SIZE}_sum'] "
                             '== 1\n'
                             '\n'
                             '\n'
                             "@pytest.mark.parametrize('reuse', ['retain', 'load', "
                             "'store'])\n"
                             'def '
                             'test_cross_agent_prefix_survives_producer_eviction(reuse):\n'
                             '    m = CPUOffloadingManager(5)\n'
                             "    a, b, c = map(context, ['writer', 'fork', "
                             "'incoming'])\n"
                             "    store(m, a, [b'prefix', b'a'])\n"
                             "    if reuse == 'retain':\n"
                             "        m.retain_context([b'prefix'], b)  # includes GPU "
                             'prefix-cache hits\n'
                             "    elif reuse == 'load':\n"
                             "        load(m, [b'prefix'], b)\n"
                             "        m.complete_load([b'prefix'], b)\n"
                             '    else:\n'
                             "        assert m.prepare_store([b'prefix'], "
                             'b).keys_to_store == []\n'
                             "    store(m, b, [b'b'], retain=[b'prefix', b'b'])\n"
                             "    before_slot = m._blocks[b'prefix'].block_id\n"
                             "    output = store(m, c, [b'c', b'd', b'e'])\n"
                             "    assert output.evicted_keys == [b'a']\n"
                             "    assert set(m._agents) == {'fork', 'incoming'}\n"
                             "    assert lookup(m, b'prefix', b) is LookupResult.HIT\n"
                             "    assert m._blocks[b'prefix'].block_id == before_slot\n"
                             "    assert lookup(m, b'b', b) is LookupResult.HIT\n"
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def '
                             'test_victim_plan_follows_shared_references_without_partial_eviction():\n'
                             '    m = CPUOffloadingManager(4)\n'
                             "    a, b, c = map(context, ['a', 'b', 'c'])\n"
                             "    store(m, a, [b'shared', b'a'])\n"
                             "    store(m, b, [b'b'], retain=[b'shared', b'b'])\n"
                             '    # Evicting A cannot reclaim the shared block while B '
                             'survives.\n'
                             "    output = store(m, c, [b'c', b'd', b'e'])\n"
                             "    assert set(output.evicted_keys) == {b'shared', b'a', "
                             "b'b'}\n"
                             "    assert set(m._agents) == {'c'}\n"
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def '
                             'test_failed_allocation_does_not_release_a_victim_or_reuse_pinned_slots():\n'
                             '    m = CPUOffloadingManager(3)\n'
                             "    a, b = map(context, ['a', 'b'])\n"
                             "    store(m, a, [b'a', b'b', b'c'])\n"
                             "    load(m, [b'a', b'b'], a)\n"
                             "    m.retain_context([b'x', b'y'], b)\n"
                             '    before_agents = {a: set(rs) for a, rs in '
                             'm._agents.items()}\n'
                             '    before_blocks = {k: (v.block_id, v.ref_cnt) for k, v '
                             'in m._blocks.items()}\n'
                             "    assert m.prepare_store([b'x', b'y'], b) is None\n"
                             '    assert before_agents == m._agents\n'
                             '    assert before_blocks == {k: (v.block_id, v.ref_cnt) '
                             'for k, v in m._blocks.items()}\n'
                             "    m.complete_load([b'a', b'b'], a)\n"
                             "    assert m.prepare_store([b'x', b'y'], b) is not None\n"
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def '
                             'test_transfer_pins_survive_reference_eviction_and_finish_independently():\n'
                             '    m = CPUOffloadingManager(4)\n'
                             "    a, b = map(context, ['a', 'b'])\n"
                             "    store(m, a, [b'a', b'b', b'c'])\n"
                             "    slot = m._blocks[b'a'].block_id\n"
                             "    load(m, [b'a'], a)\n"
                             "    store(m, b, [b'x', b'y'])\n"
                             "    assert 'a' not in m._agents\n"
                             "    assert m._blocks[b'a'].block_id == slot\n"
                             "    assert m._blocks[b'a'].ref_cnt == 1\n"
                             "    m.complete_load([b'a'], a)\n"
                             "    store(m, b, [b'x', b'y', b'z', b'w'])\n"
                             "    assert b'a' not in m._blocks\n"
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def '
                             'test_advancing_window_reclaims_old_state_without_evicting_another_agent():\n'
                             '    m = CPUOffloadingManager(6)\n'
                             "    a, b = map(context, ['a', 'b'])\n"
                             "    store(m, a, [b'p', b'old-state'])\n"
                             "    store(m, b, [b'q', b'other-state'])\n"
                             "    store(m, a, [b'p', b'p2', b'new-state'])\n"
                             "    store(m, a, [b'p', b'p2', b'p3', b'latest-state'])\n"
                             "    assert set(m._agents) == {'a', 'b'}\n"
                             "    assert lookup(m, b'q', b) is LookupResult.HIT\n"
                             "    assert lookup(m, b'other-state', b) is "
                             'LookupResult.HIT\n'
                             "    assert not {b'old-state', b'new-state'} & "
                             'm._blocks.keys()\n'
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def '
                             'test_finished_context_is_retained_and_new_turn_replaces_it():\n'
                             '    m = CPUOffloadingManager(4)\n'
                             "    first, second = context('a', 'first'), context('a', "
                             "'second')\n"
                             "    store(m, first, [b'old-prefix', b'old-state'])\n"
                             '    m.on_request_finished(first)\n'
                             '    assert first.req_id in m._contexts\n'
                             '    assert m.on_new_request(second).policy == '
                             'OffloadPolicy.REQUEST_LEVEL\n'
                             '    m.retain_context([], second)\n'
                             '    assert first.req_id in m._contexts\n'
                             "    store(m, second, [b'new-prefix', b'new-state'])\n"
                             '    assert first.req_id not in m._contexts\n'
                             '    assert second.req_id in m._contexts\n'
                             '    m.on_request_finished(second)\n'
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def '
                             'test_concurrent_requests_under_one_agent_keep_distinct_working_sets():\n'
                             '    m = CPUOffloadingManager(6)\n'
                             "    a, b = context('agent', 'one'), context('agent', "
                             "'two')\n"
                             "    store(m, a, [b'shared', b'one'])\n"
                             "    store(m, b, [b'shared', b'two'])\n"
                             '    m.on_request_finished(a)\n'
                             "    assert set(m._contexts) == {'one', 'two'}\n"
                             "    m.retain_context([b'shared', b'three'], b)\n"
                             "    assert set(m._contexts) == {'two'}\n"
                             "    assert m._references[b'shared'] == {'two'}\n"
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def '
                             'test_failed_shared_store_releases_every_incomplete_context():\n'
                             '    m = CPUOffloadingManager(4)\n'
                             "    a, b, c = map(context, ['a', 'b', 'c'])\n"
                             "    output = store(m, a, [b'pending'], complete=False)\n"
                             "    store(m, c, [b'complete'])\n"
                             "    m.retain_context([b'pending'], b)\n"
                             '    m.on_request_finished(a)\n'
                             '    m.on_request_finished(b)\n'
                             '    m.complete_store(output.keys_to_store, a, '
                             'success=False)\n'
                             "    assert set(m._agents) == {'c'}\n"
                             "    assert lookup(m, b'complete', c) is "
                             'LookupResult.HIT\n'
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def test_incomplete_finished_context_is_not_retained():\n'
                             '    m = CPUOffloadingManager(2)\n'
                             "    a = context('a')\n"
                             "    m.retain_context([b'missing'], a)\n"
                             '    m.on_request_finished(a)\n'
                             '    assert not m._contexts\n'
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def window_context(agent, available=None, '
                             'required=None):\n'
                             "    key = b'end'\n"
                             "    content = (b'early', b'middle', key)\n"
                             '    ctx = ReqContext(agent, kv_scope=agent, '
                             'prefix_content={key: content})\n'
                             '    if available is not None:\n'
                             '        ctx.prefix_store[key] = available\n'
                             '    ctx.prefix_required[key] = content if required is '
                             'None else required\n'
                             '    return ctx\n'
                             '\n'
                             '\n'
                             'def '
                             'test_sparse_window_is_local_and_fill_preserves_existing_agents():\n'
                             '    m = CPUOffloadingManager(3, enable_events=True)\n'
                             "    key = b'end'\n"
                             "    suffix = (b'middle', key)\n"
                             "    writer = window_context('writer', available=suffix, "
                             'required=suffix)\n'
                             '    store(m, writer, [key])\n'
                             '    m.on_request_finished(writer)\n'
                             '    assert writer.req_id in m._contexts\n'
                             '    assert lookup(m, key, writer) is LookupResult.HIT\n'
                             "    assert m._lookup(key, ReqContext('storage')) is "
                             'LookupResult.MISS\n'
                             '    assert list(m.take_events()) == []\n'
                             '    with pytest.raises(AssertionError):\n'
                             "        m.prepare_read([key], ReqContext('storage'))\n"
                             "    fork = window_context('fork', required=suffix)\n"
                             '    load(m, [key], fork)\n'
                             '    m.complete_load([key], fork)\n'
                             '    slot = m._blocks[key].block_id\n'
                             "    earlier = window_context('earlier')\n"
                             '    assert lookup(m, key, earlier) is LookupResult.MISS\n'
                             '\n'
                             '    output = store(m, earlier, [key], complete=False)\n'
                             '    assert output.keys_to_store == [key]\n'
                             '    assert list(output.store_spec.block_ids) == [slot]\n'
                             '    assert m._num_allocated_blocks == 1\n'
                             '    assert lookup(m, key, earlier) is '
                             'LookupResult.HIT_PENDING\n'
                             "    assert m._available_content[key] == (b'early', "
                             '*suffix)\n'
                             "    for agent in ['writer', 'fork']:\n"
                             '        assert m._contexts[agent].keys == {key}\n'
                             '    m.complete_store(output.keys_to_store, earlier)\n'
                             '    assert lookup(m, key, earlier) is LookupResult.HIT\n'
                             "    assert m._lookup(key, ReqContext('storage')) is "
                             'LookupResult.HIT\n'
                             '    events = list(m.take_events())\n'
                             '    assert [(e.keys, e.removed) for e in events] == '
                             '[([key], False)]\n'
                             '    # The filled row serves every reader whose required '
                             'data it holds,\n'
                             '    # including the agents that wrote or read only its '
                             'suffix before.\n'
                             "    for agent in ['writer', 'fork']:\n"
                             '        assert lookup(m, key, window_context(agent)) is '
                             'LookupResult.HIT\n'
                             '    check(m)\n'
                             '\n'
                             '\n'
                             "@pytest.mark.parametrize('pin', ['reader', 'writer'])\n"
                             'def '
                             'test_sparse_fill_waits_for_transfers_without_partial_allocation(pin):\n'
                             '    m = CPUOffloadingManager(3)\n'
                             "    key = b'end'\n"
                             "    suffix = (b'middle', key)\n"
                             "    writer = window_context('writer', available=suffix, "
                             'required=suffix)\n'
                             '    pending = store(m, writer, [key], complete=pin == '
                             "'reader')\n"
                             "    if pin == 'reader':\n"
                             '        load(m, [key], writer)\n'
                             "    incoming = window_context('incoming')\n"
                             "    incoming.prefix_content[b'new'] = (b'new',)\n"
                             "    assert m.prepare_store([b'new', key], incoming) is "
                             'None\n'
                             '    assert set(m._blocks) == {key}\n'
                             '    assert m._available_content[key] == suffix\n'
                             "    if pin == 'reader':\n"
                             '        m.complete_load([key], writer)\n'
                             '    else:\n'
                             '        m.complete_store(pending.keys_to_store, writer)\n'
                             "    result = m.prepare_store([b'new', key], incoming)\n"
                             "    assert result.keys_to_store == [b'new', key]\n"
                             '    assert list(result.store_spec.block_ids) == [1, 0]\n'
                             '    assert m._num_write_pending_blocks == 2\n'
                             '    m.complete_store(result.keys_to_store, incoming)\n'
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def '
                             'test_failed_fill_drops_dependent_contexts_and_cannot_export():\n'
                             '    m = CPUOffloadingManager(3)\n'
                             "    suffix = (b'middle', b'end')\n"
                             "    writer = window_context('writer', available=suffix, "
                             'required=suffix)\n'
                             "    store(m, writer, [b'end'])\n"
                             "    fork = window_context('fork', required=suffix)\n"
                             "    load(m, [b'end'], fork)\n"
                             "    m.complete_load([b'end'], fork)\n"
                             "    incoming = window_context('incoming')\n"
                             "    output = store(m, incoming, [b'end'], "
                             'complete=False)\n'
                             '    m.complete_store(output.keys_to_store, incoming, '
                             'success=False)\n'
                             '    assert not m._contexts and not m._blocks\n'
                             '    assert not m._complete_blocks and not '
                             'm._canonical_content\n'
                             '    assert not m._available_content\n'
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def '
                             'test_retained_context_requires_coverage_of_its_whole_window():\n'
                             '    m = CPUOffloadingManager(2)\n'
                             "    writer = window_context('writer', "
                             "available=(b'middle', b'end'))\n"
                             "    store(m, writer, [b'end'])\n"
                             '    m.on_request_finished(writer)\n'
                             '    assert writer.req_id not in m._contexts\n'
                             "    assert m._available_content[b'end'] == (b'middle', "
                             "b'end')\n"
                             '    check(m)\n'
                             '\n'
                             '\n'
                             "@pytest.mark.parametrize('bad', [None, '', ' ', 4, "
                             'False])\n'
                             "@pytest.mark.parametrize('keys', [[], [b'new']])\n"
                             'def '
                             'test_agent_validation_precedes_mutation_even_on_noop_store(bad, '
                             'keys):\n'
                             '    m = CPUOffloadingManager(1)\n'
                             "    a = context('a')\n"
                             "    store(m, a, [b'existing'])\n"
                             "    ctx = ReqContext(req_id='bad', kv_scope=bad)\n"
                             "    with pytest.raises(VLLMServerError, match='agent "
                             "ID'):\n"
                             '        m.prepare_store(keys, ctx)\n'
                             "    assert set(m._blocks) == {b'existing'}\n"
                             "    assert set(m._agents) == {'a'}\n"
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def '
                             'test_duplicate_keys_allocate_once_and_load_order_is_preserved():\n'
                             '    m = CPUOffloadingManager(3)\n'
                             "    a = context('a')\n"
                             "    output = store(m, a, [b'1', b'2', b'1', b'3'])\n"
                             "    assert output.keys_to_store == [b'1', b'2', b'3']\n"
                             "    spec = load(m, [b'3', b'1', b'2'], a)\n"
                             '    assert list(spec.block_ids) == [2, 0, 1]\n'
                             "    m.complete_load([b'3', b'1', b'2'], a)\n"
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def '
                             'test_reset_discards_all_references_and_transfer_accounting():\n'
                             '    m = CPUOffloadingManager(4)\n'
                             "    a, b = context('a'), context('b')\n"
                             "    store(m, a, [b'1', b'2'])\n"
                             "    load(m, [b'1'], a)\n"
                             "    store(m, b, [b'3'], complete=False, retain=[b'1', "
                             "b'3'])\n"
                             '    m.reset_cache()\n'
                             '    assert not m._contexts and not m._references and not '
                             'm._idle_context\n'
                             '    assert not m._blocks and not m._free_list\n'
                             '    assert m._num_allocated_blocks == 0\n'
                             "    store(m, a, [b'4', b'5', b'6', b'7'])\n"
                             '    check(m)\n'
                             '\n'
                             '\n'
                             'def test_removed_events_precede_new_store_events():\n'
                             '    m = CPUOffloadingManager(2, enable_events=True)\n'
                             "    a, b = context('a'), context('b')\n"
                             "    store(m, a, [b'1', b'2'])\n"
                             '    list(m.take_events())\n'
                             "    store(m, b, [b'3'])\n"
                             '    events = list(m.take_events())\n'
                             '    assert [(e.keys, e.removed) for e in events] == '
                             "[([b'1', b'2'], True), ([b'3'], False)]\n"
                             '    assert list(m.take_events()) == []\n'
                             '\n'
                             '\n'
