                      '    vllm_config = '
                      'VllmConfig(model_config=ModelConfig(max_model_len=max_model_len))\n'
                      '    vllm_config.cache_config.kv_cache_users = kv_cache_users\n'
                      '    return vllm_config\n'
                      '\n'
                      '\n'
                      'def _blocks_per_user(max_model_len: int) -> int:\n'
                      '    return cdiv(max_model_len, BLOCK_SIZE)\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("users", [1, 3])\n'
                      '@pytest.mark.parametrize("max_model_len", [16, 48, 50])\n'
