                      '    with pytest.raises(ValueError, match="cpu_kv_cache_users '
                      'must be specified"):\n'
                      '        _create_spec(cpu_kv_cache_users=None)\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("bad_users", [0, -1, 1.5, "1", True])\n'
                      'def '
                      'test_cpu_spec_rejects_non_positive_or_non_integer_users(bad_users):\n'
                      '    with pytest.raises(ValueError, match="positive integer"):\n'
                      '        _create_spec(cpu_kv_cache_users=bad_users)\n'
                      '\n'
                      '\n'
                      'def test_cpu_spec_unknown_extra_config_key_fails_startup():\n'
                      '    with pytest.raises(ValueError, match="does not act on '
                      'kv_connector_extra_config"):\n'
                      '        _create_spec(extra_config={"definitely_not_a_knob": '
                      '1})\n'
                      '\n'
                      '\n'
                      'def '
                      'test_only_the_spec_that_certifies_a_canonical_layout_accepts_it():\n'
                      "    # The CPU spec's worker keeps the direct layout, so a "
                      'canonical_layout\n'
                      '    # request it accepted would be ignored; the tiering spec '
                      'certifies and\n'
                      '    # honours it.\n'
                      '    assert "canonical_layout" not in '
                      'CPUOffloadingSpec.EXTRA_CONFIG_KEYS\n'
                      '    assert "canonical_layout" in '
                      'TieringOffloadingSpec.EXTRA_CONFIG_KEYS\n'
                      '    with pytest.raises(ValueError, match="canonical_layout"):\n'
                      '        _create_spec(extra_config={"canonical_layout": True})\n'
                      '\n'
                      '\n'
                      'def test_cpu_spec_user_count_scales_capacity():\n'
                      '    # 128-token contexts over 16-token chunks: 8 chunks per '
                      'declared user.\n'
                      '    assert _create_spec(cpu_kv_cache_users=1).num_blocks == 8\n'
                      '    assert _create_spec(cpu_kv_cache_users=4).num_blocks == 32\n'
                      '\n'
                      '\n'
                      'def '
                      'test_cpu_spec_windowed_group_counts_trailing_window_only():\n'
                      '    # A full-attention group needs its whole prefix; a '
                      'recurrent/windowed\n'
                      '    # group is resident at the trailing window the load path '
                      'reads. For a\n'
                      '    # Mamba-style window of one chunk, one 128-token user is 8 '
                      '+ 1 chunks,\n'
                      '    # not 8 + 8: counting every boundary snapshot would double '
                      'the declared\n'
                      '    # footprint for chunks a full-length re-entry never reads.\n'
                      '    groups = (\n'
                      '        OffloadingGroupConfig(16, ("full_layer",)),\n'
                      '        OffloadingGroupConfig(16, ("mamba_layer",), '
                      'sliding_window_size_in_chunks=1),\n'
                      '    )\n'
                      '    spec = _create_spec(groups=groups)\n'
                      '    assert spec.num_blocks == 9\n'
                      '\n'
                      '\n'
                      'def test_cpu_spec_window_wider_than_context_is_clamped():\n'
                      '    groups = (\n'
                      '        OffloadingGroupConfig(16, ("swa_layer",), '
                      'sliding_window_size_in_chunks=99),\n'
                      '    )\n'
                      '    spec = _create_spec(groups=groups)\n'
                      '    assert spec.num_blocks == 8\n'
                      '\n'
                      '\n'
                      'def '
