                      '    The mock tokenizer decodes an unknown ASCII id to its '
                      'character, so a\n'
                      '    plain token is one character with its code point as the '
                      'id.\n'
                      '    """\n'
                      '    ids = [VOCAB[piece] if piece in VOCAB else ord(piece) for '
                      'piece in pieces]\n'
                      '    return "".join(pieces), ids\n'
                      '\n'
                      '\n'
                      '@pytest.fixture\n'
                      'def tokenizer():\n'
                      '    return make_mock_tokenizer(VOCAB)\n'
                      '\n'
                      '\n'
                      '@pytest.fixture\n'
                      'def request_stub():\n'
                      '    req = MagicMock(spec=ChatCompletionRequest)\n'
                      '    req.tools = []\n'
                      '    req.tool_choice = "auto"\n'
                      '    req.include_reasoning = True\n'
                      '    return req\n'
                      '\n'
                      '\n'
                      '@pytest.fixture\n'
                      'def composed_parser(tokenizer):\n'
                      '    """The parser the chat endpoint builds for this '
