                      '        with pytest.raises(VLLMValidationError):\n'
                      '            _convert(request)\n'
                      '\n'
                      '    @pytest.mark.parametrize(\n'
                      '        "source",\n'
                      '        [None, {"type": "url"}, {"type": "base64", '
                      '"media_type": "image/png"}],\n'
                      '        ids=["no-source", "url-without-url", '
                      '"base64-without-data"],\n'
                      '    )\n'
                      '    def test_an_image_item_that_names_no_image_is_refused(self, '
                      'source):\n'
                      '        item = {"type": "image"} if source is None else '
                      '{"type": "image", "source": source}\n'
                      '        request = self._request([item])\n'
                      '\n'
                      '        with pytest.raises(VLLMValidationError) as refusal:\n'
                      '            _convert(request)\n'
                      '\n'
                      '        assert "names no image" in str(refusal.value)\n'
                      '\n'
                      '    def '
                      'test_a_user_image_block_that_names_no_image_is_refused(self):\n'
                      '        request = _make_request(\n'
                      '            [{"role": "user", "content": [{"type": "image", '
                      '"source": {"type": "url"}}]}]\n'
                      '        )\n'
                      '\n'
                      '        with pytest.raises(VLLMValidationError) as refusal:\n'
                      '            _convert(request)\n'
                      '\n'
                      '        assert "an image block in a user message names no '
                      'image" in str(refusal.value)\n'
                      '\n'
                      '    def test_is_error_is_stated_before_string_content(self):\n'
                      '        request = self._request("ENOENT: no such file", '
                      'is_error=True)\n'
                      '        result = _convert(request)\n'
                      '\n'
                      '        tool_msg = [m for m in result.messages if m["role"] == '
                      '"tool"][0]\n'
                      '        assert tool_msg["content"] == '
                      'f"{TOOL_RESULT_ERROR_LINE}\\nENOENT: no such file"\n'
                      '\n'
                      '    def '
                      'test_is_error_with_no_content_is_the_statement_alone(self):\n'
                      '        request = self._request(None, is_error=True)\n'
                      '        result = _convert(request)\n'
