                      '"data:image/png;base64,AAAA"}},\n'
                      '        ]\n'
                      '\n'
                      '    @pytest.mark.parametrize("block", [{}, {"is_error": '
                      'False}], ids=["absent", "false"])\n'
                      '    def test_a_result_that_is_not_an_error_is_unchanged(self, '
                      'block):\n'
                      '        request = self._request("fine", **block)\n'
                      '        result = _convert(request)\n'
                      '\n'
                      '        tool_msg = [m for m in result.messages if m["role"] == '
