                      '\n'
                      'class TestErrorEnvelope:\n'
                      '    @staticmethod\n'
                      '    def _make_api_app(side_effect: Exception):\n'
                      '        app = FastAPI()\n'
                      '        attach_router(app)\n'
                      '        app.state.args = Namespace(log_error_stack=False)\n'
                      '        '
                      'app.exception_handler(RequestValidationError)(validation_exception_handler)\n'
                      '\n'
                      '        handler = MagicMock(spec=AnthropicServingMessages)\n'
                      '        handler.create_messages.side_effect = side_effect\n'
                      '        handler.count_tokens.side_effect = side_effect\n'
                      '        app.state.anthropic_serving_messages = handler\n'
                      '        return app\n'
                      '\n'
                      '    _body = {\n'
                      '        "model": "test-model",\n'
                      '        "max_tokens": 1,\n'
                      '        "messages": [{"role": "user", "content": "Hello"}],\n'
                      '        "kv_scope": "agent",\n'
                      '    }\n'
                      '\n'
                      '    @pytest.mark.parametrize(\n'
                      '        ("exc", "status", "error_type"),\n'
                      '        [\n'
                      '            (ValueError("the template refused this history"), '
                      '400, "invalid_request_error"),\n'
                      '            (TypeError("a content part of the wrong shape"), '
                      '400, "invalid_request_error"),\n'
                      '            (\n'
                      '                VLLMValidationError("kv_scope is required", '
                      'parameter="kv_scope"),\n'
                      '                400,\n'
                      '                "invalid_request_error",\n'
                      '            ),\n'
                      '            (NotImplementedError("beam search is not '
                      'supported"), 501, "api_error"),\n'
                      '            (RuntimeError("something the server did"), 500, '
                      '"api_error"),\n'
                      '        ],\n'
                      '        ids=["ValueError", "TypeError", "VLLMValidationError", '
                      '"NotImplemented", "Runtime"],\n'
                      '    )\n'
                      '    @pytest.mark.parametrize("route", ["/v1/messages", '
                      '"/v1/messages/count_tokens"])\n'
                      '    @pytest.mark.parametrize("stream", [False, True])\n'
                      '    def '
                      'test_a_refusal_is_classified_as_the_openai_surface_classifies_it(\n'
                      '        self, route, stream, exc, status, error_type\n'
                      '    ):\n'
                      '        """A prompt the template refuses, an image the media '
                      'gate refuses, a\n'
                      '        prompt longer than the window: all are ValueErrors, all '
                      'are the\n'
                      "        caller's, and all are HTTP 400 here as they are on the "
                      'OpenAI paths."""\n'
                      '        app = self._make_api_app(exc)\n'
                      '        with TestClient(app, raise_server_exceptions=False) as '
                      'client:\n'
                      '            response = client.post(route, json=self._body | '
                      '{"stream": stream})\n'
                      '\n'
                      '        assert response.status_code == status\n'
                      '        body = response.json()\n'
                      '        assert body["type"] == "error"\n'
                      '        assert body["error"]["type"] == error_type\n'
                      '        assert str(exc).split(" ")[0] in '
                      'body["error"]["message"]\n'
                      '\n'
                      '    def '
                      'test_body_validation_is_answered_in_the_anthropic_envelope(self):\n'
                      '        app = self._make_api_app(AssertionError("must not be '
                      'reached"))\n'
                      '        with TestClient(app, raise_server_exceptions=False) as '
                      'client:\n'
                      '            response = client.post("/v1/messages", '
                      'json=self._body | {"max_tokens": 0})\n'
                      '\n'
                      '        assert response.status_code == HTTPStatus.BAD_REQUEST\n'
                      '        body = response.json()\n'
                      '        assert body["type"] == "error"\n'
                      '        assert body["error"]["type"] == '
                      '"invalid_request_error"\n'
                      '        assert "max_tokens" in body["error"]["message"]\n'
                      '\n'
                      '    @pytest.mark.parametrize(\n'
                      '        ("code", "error_type"),\n'
                      '        [\n'
                      '            (400, "invalid_request_error"),\n'
                      '            (404, "not_found_error"),\n'
                      '            (413, "request_too_large"),\n'
                      '            (422, "invalid_request_error"),\n'
                      '            (429, "rate_limit_error"),\n'
                      '            (500, "api_error"),\n'
                      '            (503, "api_error"),\n'
                      '            (529, "overloaded_error"),\n'
                      '        ],\n'
                      '    )\n'
                      '    def test_an_engine_refusal_is_typed_by_its_status(self, '
                      'code, error_type):\n'
                      '        translated = translate_error_response(\n'
                      '            ErrorResponse(\n'
                      '                error=ErrorInfo(message="why", '
                      'type="BadRequestError", code=code)\n'
