                      '    @pytest.mark.asyncio\n'
                      '    @pytest.mark.parametrize("code,kind", [(400, '
                      '"invalid_request_error"), (500, "api_error")])\n'
                      '    async def '
                      'test_stream_forwards_the_classified_error_and_never_reports_success(self, '
                      'code, kind):\n'
                      '        async def upstream():\n'
                      '            yield '
                      '_make_stream_chunk(delta=DeltaMessage(role="assistant"))\n'
                      "            yield 'data: ' + ErrorResponse(\n"
                      '                error=ErrorInfo(message="why", '
                      'type="OpenAIError", code=code)\n'
                      "            ).model_dump_json() + '\\n\\n'\n"
