                      '        assert events[-1] == ("error", {"type": "error", '
                      '"error": {"type": kind, "message": "why"}})\n'
                      '        assert not any(kind in ("message_delta", '
                      '"message_stop") for kind, _ in events)\n'
                      '\n'
                      '    @pytest.mark.parametrize("route", ["/v1/messages", '
                      '"/v1/messages/count_tokens"])\n'
