                      '    @pytest.mark.parametrize("gate", ["template", "image", '
                      '"length"])\n'
                      '    def '
                      'test_real_request_gates_return_400_before_streaming(self, '
                      'route, stream, gate, monkeypatch):\n'
                      '        from vllm.entrypoints.serve.utils.api_utils import '
                      'get_max_tokens\n'
                      '        from vllm.multimodal.media.image import ImageMediaIO\n'
                      '        from vllm.renderers.hf import safe_apply_chat_template\n'
                      '        import jinja2\n'
                      '\n'
                      '\n'
                      '        async def reject(*args):\n'
                      '            if gate == "length":\n'
                      '                get_max_tokens(32, 1, 33, {})\n'
                      '            elif gate == "image":\n'
                      '                ImageMediaIO(image_mode="RGBA")\n'
                      '            else:\n'
