                             '\n'
                             'import json\n'
                             'from unittest.mock import MagicMock\n'
                             '\n'
                             'import pytest\n'
                             '\n'
                             'from vllm.entrypoints.openai.chat_completion.protocol '
                             'import ChatCompletionRequest\n'
                             'from vllm.entrypoints.openai.chat_completion.serving '
                             'import OpenAIServingChat\n'
                             'from vllm.entrypoints.openai.engine.protocol import '
                             'RequestResponseMetadata\n'
                             'from vllm.outputs import CompletionOutput, '
                             'RequestOutput\n'
                             'from vllm.parser import ParserManager\n'
                             '\n'
                             '\n'
                             'MARKERS = {"</think>": 20000, "<tool_call>": 20001, '
