                      '    captured = []\n'
                      '\n'
                      '    async def engine_generate(prompt, params, request_id, '
                      '**kwargs):\n'
                      '        captured.append(params)\n'
                      '        yield RequestOutput(\n'
                      '            request_id=request_id, prompt=None, '
                      'prompt_token_ids=[1, 2, 3],\n'
                      '            prompt_logprobs=None, finished=True,\n'
                      '            outputs=[CompletionOutput(\n'
