                      '        errored=False, generate=engine_generate,\n'
                      '        '
                      'vllm_config=SimpleNamespace(scheduler_config=SimpleNamespace(max_num_seqs=1)),\n'
                      '    )\n'
                      '    request = generate(settings)\n'
                      '    request.stream = stream\n'
                      '    before = request.model_dump_json()\n'
