                      '\n'
                      '\n'
                      'def test_resolved_nested_settings_do_not_alias_the_request():\n'
                      '    request = generate({\n'
                      '        "structured_outputs": {"json": {"type": "object", '
                      '"properties": {}}},\n'
                      '        "extra_args": {"custom": {"value": "original"}},\n'
                      '    })\n'
                      '    request.kv_transfer_params = {"remote": {"value": '
                      '"original"}}\n'
                      '    request.ec_transfer_params = {"remote": {"value": '
                      '"original"}}\n'
                      '    before = request.model_dump_json()\n'
                      '    params = request.to_sampling_params(509, DEFAULTS)\n'
                      '    params.extra_args["custom"]["value"] = "engine"\n'
                      '    params.extra_args["kv_transfer_params"]["remote"]["value"] '
                      '= "engine"\n'
                      '    params.extra_args["ec_transfer_params"]["remote"]["value"] '
                      '= "engine"\n'
                      '    params.structured_outputs.json["properties"]["added"] = '
                      '{"type": "string"}\n'
                      '    assert request.model_dump_json() == before\n'
                      '\n'
                      '\n'
                      '@pytest.mark.asyncio\n'
                      '@pytest.mark.parametrize("surface", ["chat", "completion"])\n'
                      '@pytest.mark.parametrize("requested_max, expected_max", [(None, '
                      '509), (16, 16)])\n'
                      'async def '
                      'test_rendered_requests_keep_resolved_sampling_through_generate_json(\n'
                      '    surface, requested_max, expected_max,\n'
                      '):\n'
                      '    from types import SimpleNamespace\n'
                      '    from unittest.mock import AsyncMock\n'
                      '\n'
                      '    from vllm.entrypoints.scale_out.render.serving import '
                      'ServingRender\n'
                      '\n'
                      '    render = object.__new__(ServingRender)\n'
                      '    render.model_config = SimpleNamespace(max_model_len=512, '
                      'is_encoder_decoder=False)\n'
                      '    render.default_sampling_params = dict(DEFAULTS)\n'
                      '    render.override_max_tokens = None\n'
                      '    render._check_model = AsyncMock(return_value=None)\n'
                      '    prompt = {"type": "token", "prompt_token_ids": [1, 2, 3]}\n'
                      '    render.online_renderer = SimpleNamespace(\n'
                      '        render_chat=AsyncMock(return_value=(None, [prompt])),\n'
                      '        render_completion=AsyncMock(return_value=[prompt]),\n'
                      '    )\n'
                      '    kwargs = {"model": "model", "max_tokens": requested_max, '
                      '"temperature": 1.0,\n'
                      '              "top_p": 1.0, "top_k": 0, '
                      '"thinking_token_budget": None}\n'
                      '    if surface == "chat":\n'
                      '        request = ChatCompletionRequest(messages=[{"role": '
                      '"user", "content": "hi"}], **kwargs)\n'
                      '        rendered = await render.render_chat_request(request)\n'
                      '    else:\n'
                      '        request = CompletionRequest(prompt="hi", **kwargs)\n'
                      '        rendered, = await '
                      'render.render_completion_request(request)\n'
                      '    payload = rendered.model_dump_json()\n'
                      '    assert "kv_scope" not in json.loads(payload)\n'
                      '    # Rendering names no line of work; the caller adds one to '
                      'generate.\n'
                      '    incoming = TokenGenerationRequest.model_validate(\n'
                      '        {**json.loads(payload), "kv_scope": "agent"}\n'
                      '    )\n'
                      '    assert incoming.sampling_params["max_tokens"] == '
                      'expected_max\n'
                      '    params = incoming.to_sampling_params(expected_max, '
                      '{**DEFAULTS, "top_p": 0.2})\n'
                      '    assert params.max_tokens == expected_max\n'
                      '    assert (params.temperature, params.top_p, params.top_k) == '
                      '(1.0, 1.0, 0)\n'
                      '    assert params.thinking_token_budget is None\n'
                      '    assert params.final_response_token_budget == 100\n'
                      '    assert params.extra_args["kv_scope"] == "agent"\n'
                      '\n'
                      '\n'
                      'def '
                      'test_sampling_schema_preserves_omission_and_exposes_only_request_inputs():\n'
                      '    schema = GenerateRequest.model_json_schema()\n'
                      '    sampling = schema["properties"]["sampling_params"]\n'
                      '    assert sampling["type"] == "object"\n'
                      '    assert sampling["additionalProperties"] is False\n'
                      '    assert not sampling.get("required")\n'
                      '    assert "default" not in '
                      'sampling["properties"]["max_tokens"]\n'
                      '    assert {"temperature", "top_p", "top_k", '
                      '"thinking_token_budget",\n'
                      '            "final_response_token_budget", '
                      '"structured_outputs"} <= sampling["properties"].keys()\n'
                      '    assert not {"skip_clone", "output_text_buffer_length", '
                      '"_eos_token_id"} & sampling["properties"].keys()\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("value", [-2, 0, True, 1.0])\n'
