                             'from vllm.sampling_params import SamplingParams\n'
                             '\n'
                             'DEFAULTS = {\n'
                             '    "temperature": 0.8, "top_p": 0.95, "top_k": 20, '
                             '"min_p": 0.01,\n'
                             '    "presence_penalty": 0.3, "repetition_penalty": 1.1,\n'
                             '    "thinking_token_budget": 200, '
