                       'mm_engine_input["mm_hashes"]\n'
                       '        raw_placeholders: MultiModalPlaceholders = '
                       'mm_engine_input["mm_placeholders"]\n'
                       '\n'
                       '        mm_placeholders = {\n'
                       '            modality: [\n'
                       '                PlaceholderRangeInfo(offset=p.offset, '
                       'length=p.length) for p in ranges\n'
                       '            ]\n'
                       '            for modality, ranges in raw_placeholders.items()\n'
                       '        }\n'
                       '\n'
