                      'class ServingDerender(BaseServing):\n'
                      '    def __init__(\n'
                      '        self,\n'
                      '        models: OpenAIServingModels | OpenAIModelRegistry,\n'
                      '        online_derenderer: "OnlineDerenderer",\n'
                      '        *,\n'
                      '        request_logger: RequestLogger | None = None,\n'
                      '    ) -> None:\n'
                      '        super().__init__(\n'
                      '            models=models,\n'
                      '            model_config=models.model_config,\n'
