                      '\n'
                      '    def _validate_derender_bounds(\n'
                      '        self,\n'
                      '        generate_responses: list[GenerateResponse],\n'
                      '    ) -> ErrorResponse | None:\n'
                      '        """Reject derender payloads that exceed resource '
                      'bounds.\n'
                      '\n'
                      '        Runs before any tokenizer.decode() or parser invocation '
                      'to prevent\n'
                      '        CPU/memory exhaustion from oversized caller-supplied '
                      'token structures.\n'
                      '        """\n'
                      '        max_n = envs.VLLM_MAX_N_SEQUENCES\n'
                      '        max_model_len = self.model_config.max_model_len\n'
                      '        # See ModelConfig.max_logprobs for semantics and '
                      'default value.\n'
                      '        max_logprobs = self.model_config.max_logprobs\n'
                      '\n'
                      '        if len(generate_responses) > max_n:\n'
                      '            return self.create_error_response(\n'
                      '                f"generate_responses count '
                      '({len(generate_responses)}) "\n'
                      '                f"exceeds server maximum ({max_n}). "\n'
                      '                f"Set VLLM_MAX_N_SEQUENCES to increase this '
                      'limit."\n'
                      '            )\n'
                      '\n'
                      '        for gen in generate_responses:\n'
                      '            if len(gen.choices) > max_n:\n'
                      '                return self.create_error_response(\n'
                      '                    f"choices count ({len(gen.choices)}) in '
                      'response "\n'
                      '                    f"\'{gen.request_id}\' exceeds server '
                      'maximum ({max_n})."\n'
                      '                )\n'
                      '\n'
                      '            for choice in gen.choices:\n'
                      '                if choice.token_ids and len(choice.token_ids) > '
                      'max_model_len:\n'
                      '                    return self.create_error_response(\n'
                      '                        f"token_ids length '
                      '({len(choice.token_ids)}) in "\n'
                      '                        f"choice {choice.index} exceeds "\n'
                      '                        f"max_model_len ({max_model_len})."\n'
                      '                    )\n'
                      '                if choice.logprobs and '
                      'choice.logprobs.content:\n'
                      '                    if len(choice.logprobs.content) > '
                      'max_model_len:\n'
                      '                        return self.create_error_response(\n'
                      '                            f"logprobs.content length "\n'
                      '                            f"({len(choice.logprobs.content)}) '
                      'in "\n'
                      '                            f"choice {choice.index} exceeds "\n'
                      '                            f"max_model_len '
                      '({max_model_len})."\n'
                      '                        )\n'
                      '                    for entry in choice.logprobs.content:\n'
                      '                        if (\n'
                      '                            max_logprobs >= 0\n'
                      '                            and entry.top_logprobs\n'
                      '                            and len(entry.top_logprobs) > '
                      'max_logprobs\n'
                      '                        ):\n'
                      '                            return self.create_error_response(\n'
                      '                                f"top_logprobs count "\n'
                      '                                f"({len(entry.top_logprobs)}) '
                      'in "\n'
                      '                                f"choice {choice.index} exceeds '
                      '"\n'
                      '                                f"max_logprobs '
                      '({max_logprobs})."\n'
                      '                            )\n'
                      '\n'
                      '            if gen.prompt_logprobs and len(gen.prompt_logprobs) '
                      '> max_model_len:\n'
                      '                return self.create_error_response(\n'
                      '                    f"prompt_logprobs length '
                      '({len(gen.prompt_logprobs)}) "\n'
                      '                    f"in response \'{gen.request_id}\' exceeds '
                      '"\n'
                      '                    f"max_model_len ({max_model_len})."\n'
                      '                )\n'
                      '\n'
                      '        return None\n'
                      '\n'
                      '    async def derender_chat_response(\n'
                      '        self,\n'
                      '        request: DerenderChatRequest,\n'
                      '    ) -> ChatCompletionResponse | ErrorResponse:\n'
                      '        """Postprocess a GenerateResponse into a '
                      'ChatCompletionResponse.\n'
                      '\n'
                      '        Non-streaming only: expects the complete '
                      'GenerateResponse with all\n'
                      '        token IDs present.  Uses ``parser.parse()`` for '
                      'one-shot extraction.\n'
                      '\n'
                      '        When ``request.chat_request`` is provided, the parser '
                      'splits the\n'
                      '        output into (reasoning, content, tool_calls).  '
                      'Otherwise falls\n'
                      '        back to plain detokenization.\n'
                      '        """\n'
                      '        error_check_ret = await self._check_model(request)\n'
                      '        if error_check_ret is not None:\n'
                      '            return error_check_ret\n'
                      '\n'
                      '        bounds_error = '
                      'self._validate_derender_bounds([request.generate_response])\n'
                      '        if bounds_error is not None:\n'
                      '            return bounds_error\n'
                      '\n'
                      '        try:\n'
                      '            choices = await '
                      'self.online_derenderer.derender_chat(\n'
                      '                request.generate_response, '
                      'request.chat_request\n'
                      '            )\n'
                      '        except ValueError as exc:\n'
                      '            return self.create_error_response(str(exc))\n'
                      '\n'
                      '        prompt_tokens = (\n'
                      '            request.prompt_tokens if request.prompt_tokens is '
                      'not None else 0\n'
                      '        )\n'
                      '        gen = request.generate_response\n'
                      '        completion_tokens = sum(len(ch.token_ids) for ch in '
                      'gen.choices if ch.token_ids)\n'
                      '        usage = UsageInfo(\n'
                      '            prompt_tokens=prompt_tokens,\n'
                      '            completion_tokens=completion_tokens,\n'
                      '            total_tokens=prompt_tokens + completion_tokens,\n'
                      '        )\n'
                      '\n'
                      '        model_name = request.model or self.models.model_name()\n'
                      '        logger.debug(\n'
                      '            "derender_chat request_id=%s model=%s choices=%d '
                      'completion_tokens=%d",\n'
                      '            gen.request_id,\n'
                      '            model_name,\n'
                      '            len(choices),\n'
                      '            completion_tokens,\n'
                      '        )\n'
                      '        return ChatCompletionResponse(\n'
                      '            id=gen.request_id,\n'
                      '            model=model_name,\n'
                      '            created=int(time.time()),\n'
                      '            choices=choices,\n'
                      '            usage=usage,\n'
                      '            prompt_logprobs=gen.prompt_logprobs,\n'
                      '            kv_transfer_params=gen.kv_transfer_params,\n'
                      '        )\n'
                      '\n'
                      '    async def derender_completion_response(\n'
                      '        self,\n'
                      '        request: DerenderCompletionRequest,\n'
                      '    ) -> CompletionResponse | ErrorResponse:\n'
                      '        """Postprocess a list of GenerateResponses into a '
                      'CompletionResponse.\n'
                      '\n'
                      '        Non-streaming only.  Mirrors the multi-prompt '
                      'completions case: one\n'
                      '        GenerateResponse per prompt, parallel to the '
                      'list[GenerateRequest]\n'
                      '        from /v1/completions/render.\n'
                      '        """\n'
                      '        error_check_ret = await self._check_model(request)\n'
                      '        if error_check_ret is not None:\n'
                      '            return error_check_ret\n'
                      '\n'
                      '        if not request.generate_responses:\n'
                      '            return '
                      'self.create_error_response("generate_responses must not be '
                      'empty")\n'
                      '\n'
                      '        bounds_error = '
                      'self._validate_derender_bounds(request.generate_responses)\n'
                      '        if bounds_error is not None:\n'
                      '            return bounds_error\n'
                      '\n'
                      '        (\n'
                      '            choices,\n'
                      '            total_prompt_tokens,\n'
                      '            total_completion_tokens,\n'
                      '        ) = await self.online_derenderer.derender_completion(\n'
                      '            request.generate_responses,\n'
                      '            request.prompt_tokens,\n'
                      '            completion_request=request.completion_request,\n'
                      '        )\n'
                      '\n'
                      '        first = request.generate_responses[0]\n'
                      '        kv_params = first.kv_transfer_params\n'
                      '        if any(\n'
                      '            r.kv_transfer_params != kv_params for r in '
                      'request.generate_responses[1:]\n'
                      '        ):\n'
                      '            logger.warning(\n'
                      '                "derender_completion: kv_transfer_params differ '
                      'across responses; "\n'
                      '                "setting to None on the aggregated response"\n'
                      '            )\n'
                      '            kv_params = None\n'
                      '\n'
                      '        usage = UsageInfo(\n'
                      '            prompt_tokens=total_prompt_tokens,\n'
                      '            completion_tokens=total_completion_tokens,\n'
                      '            total_tokens=total_prompt_tokens + '
                      'total_completion_tokens,\n'
                      '        )\n'
                      '\n'
                      '        model_name = request.model or self.models.model_name()\n'
                      '        logger.debug(\n'
                      '            "derender_completion request_id=%s model=%s '
                      'choices=%d"\n'
                      '            " completion_tokens=%d",\n'
                      '            first.request_id,\n'
                      '            model_name,\n'
                      '            len(choices),\n'
                      '            total_completion_tokens,\n'
                      '        )\n'
                      '        return CompletionResponse(\n'
                      '            id=first.request_id,\n'
                      '            model=model_name,\n'
                      '            created=int(time.time()),\n'
                      '            choices=choices,\n'
                      '            usage=usage,\n'
                      '            kv_transfer_params=kv_params,\n'
                      '        )\n'
                      '\n'
                      '    async def derender_chat_stream_response(\n'
                      '        self,\n'
                      '        request: DerenderChatStreamRequest,\n'
                      '    ) -> tuple[ChatCompletionStreamResponse, '
                      'DerenderStreamState] | ErrorResponse:\n'
                      '        """Streaming counterpart to '
                      '``derender_chat_response``.\n'
                      '\n'
                      '        Processes one ``GenerateStreamResponse`` chunk and '
                      'returns the\n'
                      '        derendered chunk together with the updated client '
                      'carried state.\n'
                      '\n'
                      '        ``parser is None`` or no ``chat_request`` until '
                      'reasoning/tool call\n'
                      '        functionality added in future PR.\n'
                      '        """\n'
                      '        error_check_ret = await self._check_model(request)\n'
                      '        if error_check_ret is not None:\n'
                      '            return error_check_ret\n'
                      '\n'
                      '        model_name = request.model or self.models.model_name()\n'
                      '        try:\n'
                      '            chunk, updated_state = await '
                      'self.online_derenderer.derender_chat_stream(\n'
                      '                model=model_name,\n'
                      '                generate_chunk=request.generate_chunk,\n'
                      '                state=request.stream_state,\n'
                      '                chat_request=request.chat_request,\n'
                      '                prompt_tokens=request.prompt_tokens,\n'
                      '            )\n'
                      '        except NotImplementedError as exc:\n'
                      '            return self.create_error_response(exc)\n'
                      '        except ValueError as exc:\n'
                      '            return self.create_error_response(str(exc))\n'
                      '        except (KeyError, IndexError) as exc:\n'
                      '            return self.create_error_response(\n'
                      '                f"invalid stream_state: detokenization failed '
                      '({exc!r})"\n'
                      '            )\n'
                      '\n'
                      '        logger.debug(\n'
                      '            "derender_chat_stream request_id=%s model=%s '
                      'delta_tokens=%d",\n'
                      '            request.generate_chunk.request_id,\n'
                      '            model_name,\n'
                      '            sum(\n'
                      '                len(c.token_ids) for c in '
                      'request.generate_chunk.choices if c.token_ids\n'
                      '            ),\n'
                      '        )\n'
                      '        return chunk, updated_state\n'
                      '\n'
                      '    async def derender_completion_stream_response(\n'
                      '        self,\n'
                      '        request: DerenderCompletionStreamRequest,\n'
                      '    ) -> tuple[CompletionStreamResponse, DerenderStreamState] | '
                      'ErrorResponse:\n'
                      '        """Streaming counterpart to '
                      '``derender_completion_response``.\n'
                      '\n'
                      '        Processes one ``GenerateStreamResponse`` chunk (one '
                      "output sequence's\n"
                      '        delta) and returns the derendered chunk and updated '
                      'state.\n'
                      '        """\n'
                      '        error_check_ret = await self._check_model(request)\n'
                      '        if error_check_ret is not None:\n'
                      '            return error_check_ret\n'
                      '\n'
                      '        model_name = request.model or self.models.model_name()\n'
                      '        try:\n'
                      '            (\n'
                      '                chunk,\n'
                      '                updated_state,\n'
                      '            ) = await '
                      'self.online_derenderer.derender_completion_stream(\n'
                      '                model=model_name,\n'
                      '                generate_chunk=request.generate_chunk,\n'
                      '                state=request.stream_state,\n'
                      '                prompt_tokens=request.prompt_tokens,\n'
                      '                completion_request=request.completion_request,\n'
                      '            )\n'
                      '        except ValueError as exc:\n'
                      '            return self.create_error_response(str(exc))\n'
                      '        except (KeyError, IndexError) as exc:\n'
                      '            return self.create_error_response(\n'
                      '                f"invalid stream_state: detokenization failed '
                      '({exc!r})"\n'
                      '            )\n'
                      '\n'
                      '        logger.debug(\n'
                      '            "derender_completion_stream request_id=%s model=%s '
                      'delta_tokens=%d",\n'
                      '            request.generate_chunk.request_id,\n'
                      '            model_name,\n'
                      '            sum(\n'
                      '                len(c.token_ids) for c in '
                      'request.generate_chunk.choices if c.token_ids\n'
                      '            ),\n'
                      '        )\n'
                      '        return chunk, updated_state\n',
