                              '    MultiModalKwargsItem,\n'
                              '    MultiModalSharedField,\n'
                              ')\n'
                              '\n'
                              '\n'
                              'def test_mm_kwargs_item_roundtrip():\n'
                              '    """Full roundtrip test with all three field types '
                              'and multiple dtypes."""\n'
                              '    e1 = MultiModalFieldElem(\n'
                              '        data=torch.zeros(1000, dtype=torch.bfloat16),\n'
                              '        field=MultiModalBatchedField(),\n'
                              '    )\n'
                              '    e2 = MultiModalFieldElem(\n'
                              '        data=torch.ones(100, dtype=torch.int32),\n'
                              '        field=MultiModalSharedField(batch_size=4),\n'
                              '    )\n'
                              '    e3 = MultiModalFieldElem(\n'
                              '        data=torch.randn(20, dtype=torch.float32),\n'
                              '        field=MultiModalFlatField(slices=[slice(0, 10), '
                              'slice(10, 20)], dim=0),\n'
                              '    )\n'
                              '\n'
                              '    item = MultiModalKwargsItem({"pixel_values": e1, '
                              '"grid_thw": e2, "embeds": e3})\n'
                              '    encoded = encode_mm_kwargs_item(item)\n'
                              '\n'
                              '    # Encoded result is a base64 string\n'
                              '    assert isinstance(encoded, str)\n'
                              '\n'
                              '    decoded = decode_mm_kwargs_item(encoded)\n'
                              '\n'
                              '    assert set(decoded.keys()) == {"pixel_values", '
                              '"grid_thw", "embeds"}\n'
                              '    assert torch.equal(item["pixel_values"].data, '
                              'decoded["pixel_values"].data)\n'
                              '    assert torch.equal(item["grid_thw"].data, '
                              'decoded["grid_thw"].data)\n'
                              '    assert torch.equal(item["embeds"].data, '
                              'decoded["embeds"].data)\n'
                              '    assert isinstance(decoded["pixel_values"].field, '
                              'MultiModalBatchedField)\n'
                              '    assert isinstance(decoded["grid_thw"].field, '
                              'MultiModalSharedField)\n'
                              '    assert isinstance(decoded["embeds"].field, '
                              'MultiModalFlatField)\n'
                              '\n'
                              '\n'
                              'def test_mm_kwargs_item_none_data():\n'
                              '    """Roundtrip with None data field."""\n'
                              '    elem = MultiModalFieldElem(\n'
                              '        data=None,\n'
                              '        field=MultiModalSharedField(batch_size=2),\n'
                              '    )\n'
                              '    item = MultiModalKwargsItem({"empty": elem})\n'
                              '    encoded = encode_mm_kwargs_item(item)\n'
                              '    decoded = decode_mm_kwargs_item(encoded)\n'
                              '\n'
                              '    assert decoded["empty"].data is None\n'
                              '    assert isinstance(decoded["empty"].field, '
                              'MultiModalSharedField)\n'
                              '\n'
                              '\n'
                              'def test_mm_kwargs_item_nested_tensors():\n'
                              '    """Roundtrip with nested tensor data."""\n'
                              '    nested = [torch.randn(3, 4), torch.randn(5, 4)]\n'
                              '    elem = MultiModalFieldElem(\n'
                              '        data=nested,\n'
                              '        field=MultiModalBatchedField(),\n'
                              '    )\n'
                              '    item = MultiModalKwargsItem({"nested": elem})\n'
                              '    encoded = encode_mm_kwargs_item(item)\n'
                              '    decoded = decode_mm_kwargs_item(encoded)\n'
                              '\n'
                              '    decoded_data = decoded["nested"].data\n'
                              '    assert len(decoded_data) == 2\n'
                              '    assert torch.equal(nested[0], decoded_data[0])\n'
                              '    assert torch.equal(nested[1], decoded_data[1])\n'
                              '\n'
                              '\n'
                              'def test_mm_features_with_kwargs_data():\n'
                              '    """Test that MultiModalFeatures can carry '
