                       '\n'
                       'class TestTextOnlyFallbackFiltering:\n'
                       '    """When token IDs are available, transitions marked\n'
                       '    skip_in_token_id_mode should be skipped."""\n'
                       '\n'
                       '    def '
                       'test_func_prefix_in_prose_demoted_in_strict_mode(self):\n'
                       '        """<function=get_time> in prose should NOT trigger a '
                       'tool call\n'
                       '        when strict mode is active."""\n'
                       '        engine = StreamingParserEngine(\n'
                       '            _func_prefix_config(), '
                       '_make_func_prefix_tokenizer()\n'
                       '        )\n'
                       '        engine.feed("prefix ", [1])\n'
                       '\n'
                       '        events = engine.feed("Use <function=get_time> to '
                       'check.", [2, 3, 4, 5])\n'
                       '        events.extend(engine.finish())\n'
                       '\n'
                       '        types = [e.type for e in events]\n'
                       '        assert EventType.TOOL_CALL_START not in types\n'
                       '        assert EventType.TEXT_CHUNK in types\n'
                       '        text = "".join(e.value for e in events if e.type == '
                       'EventType.TEXT_CHUNK)\n'
                       '        assert "<function=" in text\n'
                       '\n'
                       '    def test_normal_flow_after_tool_start_still_works(self):\n'
                       '        """TOOL_START (special token) -> FUNC_PREFIX (text) '
                       'should\n'
                       '        still parse a tool call normally in strict mode."""\n'
                       '        engine = StreamingParserEngine(\n'
                       '            _func_prefix_config(), '
                       '_make_func_prefix_tokenizer()\n'
                       '        )\n'
                       '\n'
                       '        events1 = engine.feed("<tool_call>", '
                       '[_TOOL_START_ID])\n'
                       '        assert any(e.type == EventType.TOOL_CALL_START for e '
                       'in events1)\n'
                       '\n'
                       '        events2 = engine.feed("<function=get_weather>", [2, '
                       '3])\n'
                       '        events3 = engine.feed("args", [4])\n'
                       '        events4 = engine.feed("</function>", [5, 6])\n'
                       '        events4.extend(engine.feed("</tool_call>", '
                       '[_TOOL_END_ID]))\n'
                       '        events4.extend(engine.finish())\n'
                       '\n'
                       '        all_events = events1 + events2 + events3 + events4\n'
                       '        assert sum(1 for e in all_events if e.type == '
                       'EventType.TOOL_CALL_START) == 1\n'
                       '        assert sum(1 for e in all_events if e.type == '
                       'EventType.TOOL_CALL_END) == 1\n'
                       '\n'
                       '    def test_fallback_fires_without_token_ids(self):\n'
                       '        """When no token IDs are provided, fallback '
                       'transitions should\n'
                       '        still fire normally."""\n'
                       '        engine = StreamingParserEngine(\n'
                       '            _func_prefix_config(), '
                       '_make_func_prefix_tokenizer()\n'
                       '        )\n'
                       '\n'
                       '        events = '
                       'engine.feed("<function=get_time>args</function>", [])\n'
                       '        events.extend(engine.finish())\n'
                       '\n'
                       '        types = [e.type for e in events]\n'
                       '        assert EventType.TOOL_CALL_START in types\n'
                       '        assert EventType.TOOL_CALL_END in types\n'
                       '\n'
                       '    def '
                       'test_tool_between_fallback_blocked_in_strict_mode(self):\n'
                       '        """The (TOOL_BETWEEN, FUNC_PREFIX) fallback should '
                       'also be\n'
                       '        blocked in strict mode."""\n'
                       '        engine = StreamingParserEngine(\n'
                       '            _func_prefix_config(), '
                       '_make_func_prefix_tokenizer()\n'
                       '        )\n'
                       '\n'
                       '        engine.feed("<tool_call>", [_TOOL_START_ID])\n'
