                      '            '
                      '"<tool_call>\\n<function=write>\\n<parameter=text>kept</parameter>"\n'
                      '            "\\n</function></tool_call>", "stop", None, False,\n'
                      '            id="missing-newline-before-wrapper-is-raw",\n'
                      '        ),\n'
                      '        pytest.param(\n'
                      '            '
                      '"<tool_call>\\n<function=write>\\n<parameter=text>kept</parameter>"\n'
                      '            "\\n</function>\\nextra</tool_call> after", "stop", '
                      'None, False,\n'
                      '            '
                      'id="malformed-between-function-and-wrapper-is-raw",\n'
                      '        ),\n'
                      '    ],\n'
                      ')\n'
                      '@pytest.mark.parametrize("tool_choice", [\n'
                      '    "auto", "required", {"type": "function", "function": '
                      '{"name": "write"}},\n'
                      '])\n'
                      'async def '
                      'test_served_call_requires_eos_and_observed_closing_wrapper(\n'
                      '    monkeypatch, stream, chunk_size, body, finish_reason, '
                      'stop_reason, promoted,\n'
                      '    tool_choice,\n'
                      '):\n'
                      '    """A stochastic cut or caller stop must not publish an '
                      'executable call.\n'
                      '\n'
                      '    Run the real serving generators and deployment parser with '
                      'controlled model\n'
                      '    output. The complete encoded stream proves the same outcome '
                      'for batch and\n'
                      '    both small-chunk streams; no model, transport or listener '
                      'is involved.\n'
                      '    """\n'
                      '    ids = _encode("plan</think>" + body)\n'
                      '    request = ChatCompletionRequest(\n'
                      '        model="unit", messages=[{"role": "user", "content": '
                      '"write"}],\n'
                      '        tools=TOOLS, tool_choice=tool_choice, stream=stream, '
                      'kv_scope="unit",\n'
                      '    )\n'
                      '    tokenizer = MagicMock()\n'
                      '    tokenizer.get_vocab.return_value = MARKERS\n'
                      '    tokenizer.all_special_tokens = list(MARKERS)\n'
                      '    tokenizer.all_special_ids = list(MARKERS.values())\n'
                      '    tokenizer.decode.side_effect = _decode\n'
                      '\n'
                      '    async def outputs():\n'
                      '        size = chunk_size or len(ids)\n'
                      '        for start in range(0, len(ids), size):\n'
                      '            group = ids[start:start + size]\n'
                      '            last = start + size >= len(ids)\n'
                      '            yield RequestOutput(\n'
                      '                request_id="unit", prompt="prompt", '
                      'prompt_token_ids=[1, 2, 3],\n'
                      '                prompt_logprobs=None, '
                      'outputs=[CompletionOutput(\n'
                      '                    index=0, text=_decode(group), '
                      'token_ids=group,\n'
                      '                    cumulative_logprob=None, logprobs=None,\n'
                      '                    finish_reason=finish_reason if last else '
                      'None,\n'
                      '                    stop_reason=stop_reason if last else None,\n'
                      '                )], finished=last,\n'
                      '            )\n'
                      '\n'
                      '    kwargs = dict(\n'
                      '        request=request, result_generator=outputs(), '
                      'request_id="chatcmpl-unit",\n'
                      '        model_name="unit", conversation=[{"role": "user", '
                      '"content": "write"}],\n'
                      '        tokenizer=tokenizer, '
                      'request_metadata=RequestResponseMetadata(request_id="unit"),\n'
                      '    )\n'
                      '    serving = _serving()\n'
                      '    if not stream:\n'
                      '        kwargs["parser"] = serving.parser_cls(tokenizer, '
                      'request.tools)\n'
                      '        response = await '
                      'serving.chat_completion_full_generator(**kwargs)\n'
                      '        choice = response.choices[0]\n'
                      '        calls = choice.message.tool_calls or []\n'
                      '        content = choice.message.content or ""\n'
                      '        reasoning = choice.message.reasoning or ""\n'
                      '        terminal, actual_stop = choice.finish_reason, '
                      'choice.stop_reason\n'
                      '    else:\n'
                      '        calls, contents, reasonings, terminals = [], [], [], '
                      '[]\n'
                      '        async for event in '
                      'serving.chat_completion_stream_generator(**kwargs):\n'
                      '            if not event.startswith("data: ") or event.strip() '
                      '== "data: [DONE]":\n'
                      '                continue\n'
                      '            payload = json.loads(event[6:])\n'
                      '            assert "error" not in payload, payload\n'
                      '            for choice in payload.get("choices", []):\n'
                      '                delta = choice["delta"]\n'
                      '                calls.extend(delta.get("tool_calls") or [])\n'
                      '                contents.append(delta.get("content") or "")\n'
                      '                reasonings.append(delta.get("reasoning") or '
                      '"")\n'
                      '                if choice.get("finish_reason"):\n'
                      '                    terminals.append((choice["finish_reason"], '
                      'choice.get("stop_reason")))\n'
                      '        assert len(terminals) == 1\n'
                      '        terminal, actual_stop = terminals[0]\n'
                      '        content, reasoning = "".join(contents), '
                      '"".join(reasonings)\n'
                      '\n'
                      '    assert reasoning == "plan"\n'
                      '    assert actual_stop == stop_reason\n'
                      '    assert terminal == ("tool_calls" if promoted and '
                      'isinstance(tool_choice, str) else finish_reason)\n'
                      '    if promoted:\n'
                      '        assert calls\n'
                      '        if "<function= write >" in body:\n'
                      '            name = calls[0]["function"]["name"] if stream else '
                      'calls[0].function.name\n'
                      '            assert name == " write "\n'
                      '        if body.endswith("after"):\n'
                      '            assert content == "before  after"\n'
                      '        elif body.endswith("cut"):\n'
                      '            assert len(calls) == 1\n'
                      '            assert content == '
                      '"<tool_call>\\n<function=write>\\n<parameter=text>cut"\n'
                      '    else:\n'
                      '        assert calls == []\n'
                      '        assert content == body\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("suffix,accepted", [\n'
                      '    ("\\n</tool_call>", True), ("</tool_call>", False),\n'
                      '    ("\\nextra</tool_call>", False), ("\\n\\n</tool_call>", '
                      'False),\n'
                      '])\n'
                      'def test_call_closer_matches_the_native_grammar(suffix, '
