                      '    return EngineCoreRequest(\n'
                      '        request_id="stop-test", prompt_token_ids=[], '
                      'mm_features=None,\n'
                      '        sampling_params=params, pooling_params=None, '
                      'arrival_time=0,\n'
                      '        lora_request=None, cache_salt=None, '
                      'data_parallel_rank=None,\n'
                      '        external_req_id="stop-test", reasoning_ended=not '
                      'thinking,\n'
                      '    )\n'
                      '\n'
                      '\n'
                      'CALL = (\n'
                      '    '
                      '"<tool_call>\\n<function=write>\\n<parameter=text>{}</parameter>"\n'
