                      '\n'
                      '\n'
                      'def _described_choice(tool_choice: ToolChoice) -> str:\n'
                      '    if isinstance(tool_choice, '
                      'ChatCompletionNamedToolChoiceParam):\n'
                      '        return f"function {tool_choice.function.name!r}"\n'
                      '    if isinstance(tool_choice, ToolChoiceFunction):\n'
                      '        return f"function {tool_choice.name!r}"\n'
                      '    if isinstance(tool_choice, ToolChoiceAllowed):\n'
                      '        return f"allowed_tools ({tool_choice.mode!r})"\n'
                      '    return repr(tool_choice)\n'
                      '\n'
                      '\n'
                      'def require_choice_held(\n'
                      '    tool_choice: ToolChoice, cause: str, *, next_action: str = '
                      '""\n'
                      ') -> None:\n'
                      '    """Refuse a forced tool choice -- "required", a named '
