                      '        _unarmed_cause(model, parser_name),\n'
                      '        next_action=(\n'
                      '            ""\n'
                      '            if model is None\n'
                      '            else "Serve with VLLM_ENFORCE_STRICT_TOOL_CALLING '
                      'on, which arms "\n'
                      '            f"the {model!r} grammar that holds it"\n'
                      '        ),\n'
                      '    )\n'
                      '\n'
                      '\n'
                      'def require_unarmed_call_limit_held(\n'
                      '    model: str | None,\n'
                      '    parser_name: str,\n'
                      '    tool_choice: ToolChoice,\n'
                      '    parallel_tool_calls: bool | None,\n'
