                      '\n'
                      'def _single_run(length: int, label: int) -> tuple[tuple[int, '
                      'int], ...]:\n'
                      '    return ((length, label),) if length else ()\n'
                      '\n'
                      '\n'
                      'def _runs_of(value: str) -> tuple[tuple[int, int], ...]:\n'
                      '    if isinstance(value, AuthoredText):\n'
