                      '\n'
                      'class ControlTokenAuthorshipError(RuntimeError):\n'
                      '    """A rendered prompt spells an added token that no author '
                      'can be given for."""\n'
                      '\n'
                      '\n'
                      'class EncodedPrompt:\n'
                      '    """Token ids of an encoded prompt, with their character '
                      'offsets on demand."""\n'
                      '\n'
                      '    def __init__(\n'
                      '        self,\n'
                      '        ids: list[int],\n'
                      '        segments: list[tuple[int, int]],\n'
                      '        encodings: list[Any],\n'
                      '        cuts: list[tuple[int, int, int]],\n'
                      '    ) -> None:\n'
                      '        self.ids = ids\n'
                      '        self._segments = segments\n'
                      '        self._encodings = encodings\n'
                      '        self._cuts = cuts\n'
                      '\n'
                      '    def offsets(self) -> list[tuple[int, int]]:\n'
                      '        """``(start, end)`` in the encoded text for each token '
                      'id."""\n'
                      '        offsets: list[tuple[int, int]] = []\n'
                      '        for index, ((segment_start, _), encoding) in '
                      'enumerate(\n'
                      '            zip(self._segments, self._encodings, strict=True)\n'
                      '        ):\n'
                      '            offsets.extend(\n'
                      '                (segment_start + a, segment_start + b) for a, b '
                      'in encoding.offsets\n'
                      '            )\n'
                      '            if index < len(self._cuts):\n'
                      '                offsets.append(self._cuts[index][:2])\n'
                      '        return offsets\n'
                      '\n'
                      '\n'
                      'class TemplateTokenEncoder:\n'
                      '    """Encodes authored text so that only the template writes '
                      'added tokens.\n'
                      '\n'
                      "    Two private copies of the tokenizer's pipeline are used, "
                      'neither ever\n'
                      '    reconfigured after construction. ``marked`` keeps the added '
                      'vocabulary and is\n'
                      '    applied only to text no request wrote, to find the added '
                      'tokens the template\n'
                      '    spelled. ``ordinary`` has no added vocabulary at all (the '
                      'Rust frontend calls\n'
                      '    this ``encode_ordinary``) and encodes the text between '
                      'those tokens, so text\n'
                      '    the request wrote can only become ordinary vocabulary. '
                      'Cutting only at the\n'
                      "    template's added tokens is exactly how the tokenizer itself "
                      'segments text,\n'
                      '    so a prompt whose request text spells no added token '
                      'encodes to the ids the\n'
                      '    whole string always did.\n'
                      '    """\n'
                      '\n'
                      '    def __init__(self, pipeline_json: str) -> None:\n'
                      '        from tokenizers import Tokenizer\n'
                      '\n'
                      '        spec = json.loads(pipeline_json)\n'
                      '        marked = Tokenizer.from_str(json.dumps(spec))\n'
                      '        added = spec["added_tokens"]\n'
                      '        spec["added_tokens"] = []\n'
                      '        ordinary = Tokenizer.from_str(json.dumps(spec))\n'
                      '        for pipeline in (marked, ordinary):\n'
                      '            pipeline.no_truncation()\n'
                      '            pipeline.no_padding()\n'
                      '            pipeline.encode_special_tokens = False\n'
                      '        self._marked = marked\n'
                      '        self._ordinary = ordinary\n'
                      '        self._added = {token["id"]: token["content"] for token '
                      'in added}\n'
                      '\n'
                      '    def encode(self, text: AuthoredText) -> EncodedPrompt:\n'
                      '        """Encode ``text``; only added tokens the template '
                      'spelled are added ids."""\n'
                      '        cuts = self._template_added_tokens(text)\n'
                      '        segments = []\n'
                      '        start = 0\n'
                      '        for token_start, token_end, _ in cuts:\n'
                      '            segments.append((start, token_start))\n'
                      '            start = token_end\n'
                      '        segments.append((start, len(text)))\n'
                      '        encodings = self._ordinary.encode_batch(\n'
                      '            [str.__getitem__(text, slice(a, b)) for a, b in '
                      'segments],\n'
                      '            add_special_tokens=False,\n'
                      '        )\n'
                      '        ids: list[int] = []\n'
                      '        for index, encoding in enumerate(encodings):\n'
                      '            ids.extend(encoding.ids)\n'
                      '            if index < len(cuts):\n'
                      '                ids.append(cuts[index][2])\n'
                      '        return EncodedPrompt(ids, segments, encodings, cuts)\n'
                      '\n'
                      '    def _template_added_tokens(self, text: AuthoredText) -> '
                      'list[tuple[int, int, int]]:\n'
                      '        """Added tokens spelled outside request text, each '
                      'checked for its author."""\n'
                      '        regions = []\n'
                      '        for run_start, run_stop, label in text.runs():\n'
                      '            if label & _AUTHOR == REQUEST:\n'
                      '                continue\n'
                      '            if regions and regions[-1][1] == run_start:\n'
                      '                regions[-1] = (regions[-1][0], run_stop)\n'
                      '            else:\n'
                      '                regions.append((run_start, run_stop))\n'
                      '        encodings = self._marked.encode_batch(\n'
                      '            [str.__getitem__(text, slice(a, b)) for a, b in '
                      'regions],\n'
                      '            add_special_tokens=False,\n'
                      '        )\n'
                      '        cuts = []\n'
                      '        for (region_start, _), encoding in zip(regions, '
                      'encodings, strict=True):\n'
                      '            for token_id, (a, b) in zip(encoding.ids, '
                      'encoding.offsets, strict=True):\n'
                      '                if token_id not in self._added:\n'
                      '                    continue\n'
                      '                start, end = region_start + a, region_start + '
                      'b\n'
                      '                if text.authors(start, end) != {TEMPLATE}:\n'
                      '                    raise ControlTokenAuthorshipError(\n'
                      '                        "The rendered prompt spells the added '
                      'token "\n'
                      '                        f"{self._added[token_id]!r} at '
                      'characters {start}-{end}, "\n'
                      '                        "produced by a template operation that '
                      'does not record "\n'
                      '                        "authorship, so it cannot be known '
                      'whether the template "\n'
                      '                        "or the request wrote it. Write the '
                      'token from template "\n'
                      '                        "constants with +, ~, join, trim, '
                      'slicing or replace, or "\n'
                      '                        "teach AuthoredText the operation the '
                      'template uses."\n'
                      '                    )\n'
                      '                cuts.append((start, end, token_id))\n'
                      '        return cuts\n',
