                             '\n'
                             '\n'
                             'def _slice_runs(\n'
                             '    runs: tuple[tuple[int, int], ...], start: int, stop: '
                             'int\n'
                             ') -> tuple[tuple[int, int], ...]:\n'
                             '    sliced: list[tuple[int, int]] = []\n'
                             '    previous = 0\n'
                             '    for end, label in runs:\n'
                             '        low, high = max(previous, start), min(end, '
                             'stop)\n'
                             '        if low < high:\n'
                             '            if sliced and sliced[-1][1] == label:\n'
                             '                sliced[-1] = (high - start, label)\n'
                             '            else:\n'
                             '                sliced.append((high - start, label))\n'
                             '        previous = end\n'
                             '        if end >= stop:\n'
