                             '    return tuple(sliced)\n'
                             '\n'
                             '\n'
                             'def _is_plain_markup(value: str) -> bool:\n'
                             '    return isinstance(value, Markup) and not '
                             'isinstance(value, AuthoredText)\n'
                             '\n'
                             '\n'
