                             '        "".join(texts), _join_runs((_runs_of(text), '
                             'len(text)) for text in texts)\n'
                             '    )\n'
                             '\n'
                             '\n'
                             'class AuthoredText(str):\n'
                             '    """A string whose characters each carry who wrote '
                             'them.\n'
                             '\n'
                             '    The value is an ordinary ``str``: comparisons, '
                             'hashing, searching and every\n'
                             '    test a template applies behave exactly as for the '
                             'plain string, so attaching\n'
                             '    authorship never changes what a template renders. '
                             'Operations that build new\n'
                             '    text from it keep the authorship where they are '
                             'defined here; any other\n'
                             '    operation returns a plain ``str``, whose characters '
                             'have no author.\n'
                             '    """\n'
                             '\n'
                             '    def __new__(\n'
                             '        cls, value: object = "", runs: tuple[tuple[int, '
                             'int], ...] | None = None\n'
                             '    ) -> AuthoredText:\n'
                             '        text = super().__new__(cls, value)\n'
                             '        if runs is None:\n'
                             '            runs = (\n'
                             '                value._runs\n'
                             '                if isinstance(value, AuthoredText)\n'
                             '                else _single_run(len(text), '
                             'UNATTRIBUTED)\n'
                             '            )\n'
                             '        text._runs = runs\n'
                             '        return text\n'
                             '\n'
                             '    @classmethod\n'
                             '    def written_by(cls, value: str, author: int) -> '
                             'AuthoredText:\n'
                             '        return cls(value, _single_run(len(value), '
                             'author))\n'
                             '\n'
                             '    def _sub(self, start: int, stop: int) -> '
                             'AuthoredText:\n'
                             '        return AuthoredText(\n'
                             '            str.__getitem__(self, slice(start, stop)),\n'
                             '            _slice_runs(self._runs, start, stop),\n'
                             '        )\n'
                             '\n'
                             '    def authors(self, start: int, stop: int) -> '
                             'frozenset[int]:\n'
                             '        """The authors of the characters in ``[start, '
                             'stop)``."""\n'
                             '        ends = self.__dict__.get("_ends")\n'
                             '        if ends is None:\n'
                             '            ends = self.__dict__["_ends"] = [end for '
                             'end, _ in self._runs]\n'
                             '        index = bisect.bisect_right(ends, start)\n'
                             '        found = set()\n'
                             '        previous = ends[index - 1] if index else 0\n'
                             '        for end, label in self._runs[index:]:\n'
                             '            if previous >= stop:\n'
                             '                break\n'
                             '            found.add(label & _AUTHOR)\n'
                             '            previous = end\n'
                             '        return frozenset(found)\n'
                             '\n'
                             '    def generation_mask(self, offsets: '
                             'Iterable[tuple[int, int]]) -> list[int]:\n'
                             '        """1 for each token overlapping text inside a '
                             '``{% generation %}`` block."""\n'
                             '        spans = [\n'
                             '            (start, stop) for start, stop, label in '
                             'self.runs() if label & GENERATION\n'
                             '        ]\n'
                             '        span_ends = [stop for _, stop in spans]\n'
                             '        mask = []\n'
                             '        for token_start, token_end in offsets:\n'
                             '            # Spans are disjoint and ordered: the first '
                             'span ending after the\n'
                             '            # token starts is the one that would overlap '
                             'it.\n'
                             '            index = bisect.bisect_right(span_ends, '
                             'token_start)\n'
                             '            mask.append(int(index < len(spans) and '
                             'spans[index][0] < token_end))\n'
                             '        return mask\n'
                             '\n'
                             '    def runs(self) -> Iterable[tuple[int, int, int]]:\n'
                             '        """``(start, stop, label)`` for each maximal run '
                             'of one label."""\n'
                             '        previous = 0\n'
                             '        for end, label in self._runs:\n'
                             '            yield previous, end, label\n'
                             '            previous = end\n'
                             '\n'
                             '    def in_generation(self) -> AuthoredText:\n'
                             '        return AuthoredText(\n'
                             '            str(self),\n'
                             '            tuple((end, label | GENERATION) for end, '
                             'label in self._runs),\n'
                             '        )\n'
                             '\n'
                             '    def __add__(self, other: object) -> AuthoredText:\n'
                             '        # Markup escapes what it is added to; it keeps '
                             'that behaviour here.\n'
                             '        if not isinstance(other, str) or '
                             '_is_plain_markup(other):\n'
                             '            return NotImplemented\n'
                             '        return join_authored((self, other))\n'
                             '\n'
                             '    def __radd__(self, other: object) -> AuthoredText:\n'
                             '        if not isinstance(other, str) or '
                             '_is_plain_markup(other):\n'
                             '            return NotImplemented\n'
                             '        return join_authored((other, self))\n'
                             '\n'
                             '    def __mul__(self, count: object) -> AuthoredText:\n'
                             '        if not isinstance(count, int):\n'
