                             '\n'
                             '    def lstrip(self, chars: str | None = None) -> '
                             'AuthoredText:\n'
                             '        return self._sub(len(self) - '
                             'len(str.lstrip(self, chars)), len(self))\n'
                             '\n'
                             '    def rstrip(self, chars: str | None = None) -> '
                             'AuthoredText:\n'
                             '        return self._sub(0, len(str.rstrip(self, '
                             'chars)))\n'
                             '\n'
                             '    def removeprefix(self, prefix: str) -> '
                             'AuthoredText:\n'
                             '        if str.startswith(self, prefix):\n'
                             '            return self._sub(len(prefix), len(self))\n'
                             '        return self\n'
                             '\n'
                             '    def removesuffix(self, suffix: str) -> '
                             'AuthoredText:\n'
                             '        if suffix and str.endswith(self, suffix):\n'
                             '            return self._sub(0, len(self) - '
                             'len(suffix))\n'
                             '        return self\n'
                             '\n'
                             '    def _separated(self, pieces: list[str], separator: '
                             'str) -> list[AuthoredText]:\n'
                             '        out = []\n'
                             '        start = 0\n'
                             '        for piece in pieces:\n'
                             '            out.append(self._sub(start, start + '
                             'len(piece)))\n'
                             '            start += len(piece) + len(separator)\n'
                             '        return out\n'
                             '\n'
                             '    def _located(self, pieces: list[str]) -> '
                             'list[AuthoredText]:\n'
                             '        # Whitespace splitting: every piece starts with '
                             'a non-whitespace character\n'
                             '        # and only whitespace lies between pieces, so '
                             'each is found where it is.\n'
                             '        out = []\n'
                             '        start = 0\n'
                             '        for piece in pieces:\n'
                             '            start = str.find(self, piece, start)\n'
                             '            out.append(self._sub(start, start + '
                             'len(piece)))\n'
                             '            start += len(piece)\n'
                             '        return out\n'
                             '\n'
                             '    def split(self, sep: str | None = None, maxsplit: '
                             'int = -1) -> list[AuthoredText]:\n'
                             '        pieces = str.split(self, sep, maxsplit)\n'
                             '        if sep is None:\n'
                             '            return self._located(pieces)\n'
                             '        return self._separated(pieces, sep)\n'
                             '\n'
                             '    def rsplit(self, sep: str | None = None, maxsplit: '
                             'int = -1) -> list[AuthoredText]:\n'
                             '        pieces = str.rsplit(self, sep, maxsplit)\n'
                             '        if sep is None:\n'
                             '            return self._located(pieces)\n'
                             '        return self._separated(pieces, sep)\n'
                             '\n'
                             '    def splitlines(self, keepends: bool = False) -> '
                             'list[AuthoredText]:\n'
                             '        lines = []\n'
                             '        start = 0\n'
                             '        for kept, line in zip(\n'
                             '            str.splitlines(self, True), '
                             'str.splitlines(self, False), strict=True\n'
                             '        ):\n'
                             '            lines.append(self._sub(start, start + '
                             'len(kept if keepends else line)))\n'
                             '            start += len(kept)\n'
                             '        return lines\n'
                             '\n'
                             '    def _parted(self, head: str, found: str) -> '
                             'tuple[AuthoredText, ...]:\n'
                             '        return (\n'
                             '            self._sub(0, len(head)),\n'
                             '            self._sub(len(head), len(head) + '
                             'len(found)),\n'
                             '            self._sub(len(head) + len(found), '
                             'len(self)),\n'
                             '        )\n'
                             '\n'
                             '    def partition(self, sep: str) -> tuple[AuthoredText, '
                             '...]:\n'
                             '        head, found, _ = str.partition(self, sep)\n'
                             '        return self._parted(head, found)\n'
                             '\n'
                             '    def rpartition(self, sep: str) -> '
                             'tuple[AuthoredText, ...]:\n'
                             '        head, found, _ = str.rpartition(self, sep)\n'
                             '        return self._parted(head, found)\n'
                             '\n'
                             '    def join(self, iterable: Iterable[str]) -> '
                             'AuthoredText:\n'
                             '        parts: list[str] = []\n'
                             '        for item in iterable:\n'
                             '            if not isinstance(item, str):\n'
                             '                raise TypeError(\n'
                             '                    f"sequence item {len(parts) // 2}: '
                             'expected str instance, "\n'
                             '                    f"{type(item).__name__} found"\n'
                             '                )\n'
                             '            if parts:\n'
                             '                parts.append(self)\n'
                             '            parts.append(item)\n'
                             '        return join_authored(parts)\n'
                             '\n'
                             '    def replace(self, old: str, new: str, count: int = '
                             '-1) -> AuthoredText:\n'
                             '        if not old:\n'
                             '            return AuthoredText(str.replace(self, old, '
                             'new, count))\n'
                             '        parts: list[str] = []\n'
                             '        start = 0\n'
                             '        while count < 0 or len(parts) < 2 * count:\n'
                             '            found = str.find(self, old, start)\n'
                             '            if found < 0:\n'
                             '                break\n'
                             '            parts.append(self._sub(start, found))\n'
                             '            parts.append(new)\n'
                             '            start = found + len(old)\n'
                             '        parts.append(self._sub(start, len(self)))\n'
                             '        return join_authored(parts)\n'
                             '\n'
                             '\n'
                             'def _same_author(name: str) -> Callable[..., str]:\n'
                             '    method = getattr(str, name)\n'
                             '\n'
                             '    def transformed(self: AuthoredText, *args: Any, '
                             '**kwargs: Any) -> str:\n'
                             '        value = method(self, *args, **kwargs)\n'
                             '        labels = {label for _, label in self._runs}\n'
                             '        if len(labels) != 1:\n'
                             '            return value\n'
                             '        return AuthoredText.written_by(value, '
                             'labels.pop())\n'
                             '\n'
                             '    transformed.__name__ = name\n'
                             '    transformed.__doc__ = (\n'
                             '        f"``str.{name}``, keeping the author when one '
                             'author wrote all of it."\n'
                             '    )\n'
                             '    return transformed\n'
                             '\n'
                             '\n'
                             'for _name in ("upper", "lower", "capitalize", "title", '
                             '"swapcase", "casefold"):\n'
                             '    setattr(AuthoredText, _name, _same_author(_name))\n'
                             '\n'
                             '\n'
                             'class AuthoredMarkup(Markup, AuthoredText):\n'
                             '    """``Markup`` that keeps authorship: what ``|safe`` '
                             'returns for authored text."""\n'
                             '\n'
                             '\n'
                             'def written_by_template(value: Any) -> Any:\n'
                             '    """Mark the strings in a template-owned value as '
                             'written by the template."""\n'
                             '    return _written_by(value, TEMPLATE)\n'
                             '\n'
                             '\n'
                             'def written_by_request(value: Any) -> Any:\n'
                             '    """Mark the strings in request data as written by '
                             'the request.\n'
                             '\n'
                             '    Strings already carrying authorship keep it: those '
                             'are text the server itself\n'
                             '    placed in the conversation.\n'
                             '    """\n'
                             '    return _written_by(value, REQUEST)\n'
                             '\n'
                             '\n'
                             'def _written_by(value: Any, author: int) -> Any:\n'
                             '    if isinstance(value, AuthoredText):\n'
                             '        return value\n'
                             '    if isinstance(value, str):\n'
                             '        return AuthoredText.written_by(value, author)\n'
                             '    if isinstance(value, Mapping):\n'
                             '        return {\n'
                             '            _written_by(key, author): _written_by(item, '
                             'author)\n'
                             '            for key, item in value.items()\n'
                             '        }\n'
                             '    if isinstance(value, list):\n'
                             '        return [_written_by(item, author) for item in '
                             'value]\n'
                             '    if isinstance(value, tuple):\n'
                             '        return tuple(_written_by(item, author) for item '
                             'in value)\n'
                             '    return value\n'
                             '\n'
                             '\n'
                             'def _all_written_by_template(value: Any) -> bool:\n'
                             '    if isinstance(value, str):\n'
                             '        return isinstance(value, AuthoredText) and all(\n'
                             '            label & _AUTHOR == TEMPLATE for _, label in '
                             'value._runs\n'
                             '        )\n'
                             '    if isinstance(value, Mapping):\n'
                             '        return all(\n'
                             '            _all_written_by_template(k) and '
                             '_all_written_by_template(v)\n'
                             '            for k, v in value.items()\n'
                             '        )\n'
                             '    if isinstance(value, list | tuple):\n'
                             '        return all(_all_written_by_template(item) for '
                             'item in value)\n'
                             '    return True\n'
                             '\n'
                             '\n'
                             'class _AuthoringCodeGenerator(CodeGenerator):\n'
                             '    """Compiles every template constant as text written '
                             'by the template."""\n'
                             '\n'
                             '    def visit_Const(self, node: jinja2.nodes.Const, '
                             'frame: Any) -> None:\n'
                             '        value = node.as_const(frame.eval_ctx)\n'
                             '        if isinstance(value, str | list | tuple | '
                             'dict):\n'
                             '            '
                             'self.write(f"environment.template_value({value!r})")\n'
                             '        else:\n'
                             '            super().visit_Const(node, frame)\n'
                             '\n'
                             '    def visit_TemplateData(self, node: '
                             'jinja2.nodes.TemplateData, frame: Any) -> None:\n'
                             '        value = node.as_const(frame.eval_ctx)\n'
                             '        '
                             'self.write(f"environment.template_value({value!r})")\n'
                             '\n'
                             '    def _output_const_repr(self, group: Iterable[Any]) '
                             '-> str:\n'
                             '        return '
                             'f"environment.template_value({\'\'.join(map(str, '
                             'group))!r})"\n'
                             '\n'
                             '    def _output_child_pre(\n'
                             '        self, node: jinja2.nodes.Expr, frame: Any, '
                             'finalize: Any\n'
                             '    ) -> None:\n'
                             '        # Output is converted with ``str`` unless it '
                             'already carries authorship.\n'
                             '        self.write("environment.output_text(")\n'
                             '        if finalize.src is not None:\n'
                             '            self.write(finalize.src)\n'
                             '\n'
                             '    def visit_Concat(self, node: jinja2.nodes.Concat, '
                             'frame: Any) -> None:\n'
                             '        self.write("environment.concat((")\n'
                             '        for arg in node.nodes:\n'
                             '            self.visit(arg, frame)\n'
                             '            self.write(", ")\n'
                             '        self.write("))")\n'
                             '\n'
                             '\n'
                             'class GenerationTracker(jinja2.ext.Extension):\n'
                             '    """The ``{% generation %}`` tag: its output is '
                             'flagged for the assistant\n'
                             '    mask."""\n'
                             '\n'
                             '    tags = {"generation"}\n'
                             '\n'
                             '    def parse(self, parser: jinja2.parser.Parser) -> '
                             'jinja2.nodes.Node:\n'
                             '        lineno = next(parser.stream).lineno\n'
                             '        body = '
                             'parser.parse_statements(("name:endgeneration",), '
                             'drop_needle=True)\n'
                             '        call = self.call_method("_generation_support")\n'
                             '        return jinja2.nodes.CallBlock(call, [], [], '
                             'body).set_lineno(lineno)\n'
                             '\n'
                             '    def _generation_support(self, caller: Callable[[], '
                             'str]) -> AuthoredText:\n'
                             '        rendered = caller()\n'
                             '        if not isinstance(rendered, AuthoredText):\n'
                             '            rendered = AuthoredText(rendered)\n'
                             '        return rendered.in_generation()\n'
                             '\n'
                             '\n'
                             'def _tojson(\n'
                             '    value: Any,\n'
                             '    ensure_ascii: bool = False,\n'
                             '    indent: int | None = None,\n'
                             '    separators: tuple[str, str] | None = None,\n'
                             '    sort_keys: bool = False,\n'
                             ') -> AuthoredText:\n'
                             "    # Transformers' chat-template ``tojson``: no HTML "
                             'escaping, options exposed.\n'
                             '    # JSON of request data is request text; JSON of the '
                             "template's own data is\n"
                             '    # its own.\n'
                             '    text = json.dumps(\n'
                             '        value,\n'
                             '        ensure_ascii=ensure_ascii,\n'
                             '        indent=indent,\n'
                             '        separators=separators,\n'
                             '        sort_keys=sort_keys,\n'
                             '    )\n'
                             '    author = TEMPLATE if _all_written_by_template(value) '
                             'else REQUEST\n'
                             '    return AuthoredText.written_by(text, author)\n'
                             '\n'
                             '\n'
                             'def _safe(value: Any) -> Markup:\n'
                             '    if isinstance(value, AuthoredText):\n'
                             '        return AuthoredMarkup(value)\n'
                             '    return Markup(value)\n'
                             '\n'
                             '\n'
                             'def _keep_authorship(value: Any) -> str:\n'
                             "    # Markup's own methods escape their arguments; "
                             "Jinja's filters convert it to\n"
                             '    # a plain string first, so authored markup becomes '
                             'plain authored text here.\n'
                             '    return AuthoredText(value) if isinstance(value, '
                             'AuthoredText) else str(value)\n'
                             '\n'
                             '\n'
                             '@jinja2.pass_eval_context\n'
                             'def _replace(\n'
                             '    eval_ctx: jinja2.nodes.EvalContext,\n'
                             '    s: Any,\n'
                             '    old: Any,\n'
                             '    new: Any,\n'
                             '    count: int | None = None,\n'
                             ') -> str:\n'
                             "    # Jinja's replace without autoescaping, keeping "
                             'authorship.\n'
                             '    return _keep_authorship(s).replace(\n'
                             '        _keep_authorship(old), _keep_authorship(new), -1 '
                             'if count is None else count\n'
                             '    )\n'
                             '\n'
                             '\n'
                             '@jinja2.pass_eval_context\n'
                             'def _join(\n'
                             '    eval_ctx: jinja2.nodes.EvalContext,\n'
                             '    value: Iterable[Any],\n'
                             '    d: str = "",\n'
                             '    attribute: str | int | None = None,\n'
                             ') -> str:\n'
                             "    # Jinja's join without autoescaping, keeping "
                             'authorship.\n'
                             '    if attribute is not None:\n'
                             '        value = '
                             'map(make_attrgetter(eval_ctx.environment, attribute), '
                             'value)\n'
                             '    separator = d if isinstance(d, AuthoredText) else '
                             'AuthoredText(str(d))\n'
                             '    return separator.join(_keep_authorship(item) for '
                             'item in value)\n'
                             '\n'
                             '\n'
                             'def _raise_exception(message: str) -> None:\n'
                             '    raise jinja2.exceptions.TemplateError(message)\n'
                             '\n'
                             '\n'
                             'def _strftime_now(format: str) -> AuthoredText:\n'
                             '    return '
                             'AuthoredText.written_by(datetime.now().strftime(format), '
                             'TEMPLATE)\n'
                             '\n'
                             '\n'
                             'class '
                             'AuthoringEnvironment(ImmutableSandboxedEnvironment):\n'
                             '    """Transformers\' chat-template environment, '
                             'rendering with authorship.\n'
                             '\n'
                             '    The options, filters and globals are the ones '
                             '``transformers`` compiles chat\n'
                             '    templates with (``trim_blocks``, ``lstrip_blocks``, '
                             '``loopcontrols``, the\n'
                             '    ``generation`` tag, the unescaped ``tojson``, '
                             '``raise_exception`` and\n'
                             '    ``strftime_now``), so a template renders exactly the '
                             'text it renders there.\n'
                             '    """\n'
                             '\n'
                             '    code_generator_class = _AuthoringCodeGenerator\n'
                             '    concat = staticmethod(join_authored)\n'
                             '\n'
                             '    def __init__(self) -> None:\n'
                             '        super().__init__(\n'
                             '            trim_blocks=True,\n'
                             '            lstrip_blocks=True,\n'
                             '            extensions=[GenerationTracker, '
                             'jinja2.ext.loopcontrols],\n'
                             '        )\n'
                             '        self.filters["tojson"] = _tojson\n'
                             '        self.filters["safe"] = _safe\n'
                             '        self.filters["join"] = _join\n'
                             '        self.filters["replace"] = _replace\n'
                             '        self.globals["raise_exception"] = '
                             '_raise_exception\n'
                             '        self.globals["strftime_now"] = _strftime_now\n'
                             '\n'
                             '    @staticmethod\n'
                             '    def template_value(value: Any) -> Any:\n'
                             '        return written_by_template(value)\n'
                             '\n'
                             '    @staticmethod\n'
                             '    def output_text(value: Any) -> str:\n'
                             '        return value if isinstance(value, AuthoredText) '
                             'else str(value)\n'
                             '\n'
                             '\n'
                             '@lru_cache\n'
                             'def compile_chat_template(chat_template: str) -> '
                             'jinja2.Template:\n'
                             '    return '
                             'AuthoringEnvironment().from_string(chat_template)\n'
                             '\n'
                             '\n'
                             'def render_chat_template(\n'
                             '    chat_template: str,\n'
                             '    conversation: Sequence[Mapping[str, Any]],\n'
                             '    *,\n'
                             '    tools: Sequence[Mapping[str, Any]] | None,\n'
                             '    documents: Sequence[Mapping[str, Any]] | None,\n'
                             '    add_generation_prompt: bool,\n'
                             '    continue_final_message: bool | str,\n'
                             '    special_tokens: Mapping[str, Any],\n'
                             '    variables: Mapping[str, Any],\n'
                             '    raise_exception: Callable[[str], None],\n'
                             ') -> AuthoredText:\n'
                             '    """Render a chat template exactly as transformers '
                             'does, with authorship.\n'
                             '\n'
                             "    ``special_tokens`` (the tokenizer's "
                             '``special_tokens_map``) are the\n'
                             "    template's own vocabulary; ``conversation``, "
                             '``tools``, ``documents`` and\n'
                             "    ``variables`` are the request's. A variable of the "
                             'same name as a special\n'
                             '    token replaces it, as it does in transformers. '
                             '``continue_final_message``\n'
                             "    cuts the prompt after the final message's text, as "
                             'transformers does.\n'
                             '    """\n'
                             '    if documents is not None and not all(\n'
                             '        isinstance(document, Mapping) for document in '
                             'documents\n'
                             '    ):\n'
                             '        raise TypeError(\n'
                             '            "Documents should be a list of dicts with '
                             '\'title\' and \'text\' keys!"\n'
                             '        )\n'
                             '    if continue_final_message and '
                             'add_generation_prompt:\n'
                             '        raise ValueError(\n'
                             '            "continue_final_message and '
                             'add_generation_prompt are not compatible. "\n'
                             '            "Use continue_final_message when you want '
                             'the model to continue the "\n'
                             '            "final message, and add_generation_prompt '
                             'when you want to add a "\n'
                             '            "header that will prompt it to start a new '
                             'assistant message instead."\n'
                             '        )\n'
                             '\n'
                             '    messages = written_by_request(list(conversation))\n'
                             '    final_text = None\n'
                             '    if continue_final_message:\n'
                             '        field = (\n'
                             '            continue_final_message\n'
                             '            if isinstance(continue_final_message, str)\n'
                             '            else "content"\n'
                             '        )\n'
                             '        if (final := messages[-1].get(field)) is None:\n'
                             '            raise ValueError(\n'
                             '                "continue_final_message is set but the '
                             'final message has no "\n'
                             '                f\'"{field}" to continue!\'\n'
                             '            )\n'
                             '        if field not in chat_template:\n'
                             '            raise ValueError(\n'
                             "                f'continue_final_message is set to "
                             '"{field}" but this is not an \'\n'
                             '                "accepted field in the chat_template"\n'
                             '            )\n'
                             '        if isinstance(final, list | tuple):\n'
                             '            blocks = [dict(block) for block in final]\n'
                             '            for block in reversed(blocks):\n'
                             '                if "text" in block:\n'
                             '                    final_text = block["text"]\n'
                             '                    block["text"] = block["text"] + '
                             'CONTINUE_FINAL_MESSAGE_TAG\n'
                             '                    break\n'
                             '            else:\n'
                             '                raise ValueError(\n'
                             '                    "continue_final_message is set but '
                             'we could not find any text "\n'
                             '                    "to continue in the final message!"\n'
                             '                )\n'
                             '            messages[-1][field] = blocks\n'
                             '        else:\n'
                             '            final_text = final\n'
                             '            messages[-1][field] = final + '
                             'CONTINUE_FINAL_MESSAGE_TAG\n'
                             '\n'
                             '    context = {\n'
                             '        **{name: written_by_template(v) for name, v in '
                             'special_tokens.items()},\n'
                             '        **{name: written_by_request(v) for name, v in '
                             'variables.items()},\n'
                             '        "raise_exception": raise_exception,\n'
                             '    }\n'
                             '    rendered = '
                             'compile_chat_template(chat_template).render(\n'
                             '        messages=messages,\n'
                             '        tools=written_by_request(tools),\n'
                             '        documents=written_by_request(documents),\n'
                             '        add_generation_prompt=add_generation_prompt,\n'
                             '        **context,\n'
                             '    )\n'
                             '    if not isinstance(rendered, AuthoredText):\n'
                             '        rendered = AuthoredText(rendered)\n'
                             '\n'
                             '    if final_text is not None:\n'
                             '        tag = CONTINUE_FINAL_MESSAGE_TAG.strip()\n'
                             '        if final_text.strip() not in rendered or tag not '
                             'in rendered:\n'
                             '            raise ValueError(\n'
                             '                "continue_final_message is set but the '
                             'final message does not "\n'
                             '                "appear in the chat after applying the '
                             'chat template! This can "\n'
                             '                "happen if the chat template deletes '
                             'portions of the final "\n'
                             '                "message. Please verify the chat '
                             'template and final message in "\n'
                             '                "your chat to ensure they are '
                             'compatible."\n'
                             '            )\n'
                             '        cut = rendered.rindex(tag)\n'
                             '        if rendered[cut : cut + '
                             'len(CONTINUE_FINAL_MESSAGE_TAG)] == (\n'
                             '            CONTINUE_FINAL_MESSAGE_TAG\n'
                             '        ):\n'
                             '            rendered = rendered[:cut]\n'
                             '        else:\n'
                             '            rendered = rendered[:cut].rstrip()\n'
                             '    return rendered\n'
                             '\n'
                             '\n'
                             'class ControlTokenAuthorshipError(RuntimeError):\n'
                             '    """A rendered prompt spells an added token that no '
                             'author can be given for."""\n'
                             '\n'
                             '\n'
                             'class EncodedPrompt:\n'
                             '    """Token ids of an encoded prompt, with their '
                             'character offsets on demand."""\n'
                             '\n'
                             '    def __init__(\n'
                             '        self,\n'
                             '        ids: list[int],\n'
                             '        segments: list[tuple[int, int]],\n'
                             '        encodings: list[Any],\n'
                             '        cuts: list[tuple[int, int, int]],\n'
                             '    ) -> None:\n'
                             '        self.ids = ids\n'
                             '        self._segments = segments\n'
                             '        self._encodings = encodings\n'
                             '        self._cuts = cuts\n'
                             '\n'
                             '    def offsets(self) -> list[tuple[int, int]]:\n'
                             '        """``(start, end)`` in the encoded text for each '
                             'token id."""\n'
                             '        offsets: list[tuple[int, int]] = []\n'
                             '        for index, ((segment_start, _), encoding) in '
