                             '    def __init__(self, pipeline_json: str) -> None:\n'
                             '        from tokenizers import Tokenizer\n'
                             '\n'
                             '        spec = json.loads(pipeline_json)\n'
                             '        marked = Tokenizer.from_str(json.dumps(spec))\n'
                             '        added = spec["added_tokens"]\n'
                             '        spec["added_tokens"] = []\n'
                             '        ordinary = Tokenizer.from_str(json.dumps(spec))\n'
                             '        for pipeline in (marked, ordinary):\n'
                             '            pipeline.no_truncation()\n'
                             '            pipeline.no_padding()\n'
                             '            pipeline.encode_special_tokens = False\n'
                             '        self._marked = marked\n'
                             '        self._ordinary = ordinary\n'
                             '        self._added = {token["id"]: token["content"] for '
                             'token in added}\n'
                             '\n'
                             '    def encode(self, text: AuthoredText) -> '
                             'EncodedPrompt:\n'
                             '        """Encode ``text``; only added tokens the '
                             'template spelled are added ids."""\n'
                             '        cuts = self._template_added_tokens(text)\n'
                             '        segments = []\n'
                             '        start = 0\n'
                             '        for token_start, token_end, _ in cuts:\n'
                             '            segments.append((start, token_start))\n'
                             '            start = token_end\n'
                             '        segments.append((start, len(text)))\n'
                             '        encodings = self._ordinary.encode_batch(\n'
