                      '"""NVFP4 W4A4 layers are served by a native FP4 kernel or '
                      'refused at load."""\n'
                      '\n'
                      'from __future__ import annotations\n'
                      '\n'
                      'import pytest\n'
                      '\n'
                      'import vllm.model_executor.kernels.linear as linear\n'
