                      '    FlashInferTrtllmNvFp4LinearKernel,\n'
                      ')\n'
                      'from vllm.model_executor.kernels.linear.nvfp4.marlin import (\n'
                      '    MarlinNvFp4LinearKernel,\n'
                      ')\n'
                      'from vllm.platforms import PlatformEnum\n'
                      'from vllm.platforms.interface import DeviceCapability\n'
                      '\n'
                      '\n'
                      'def device(monkeypatch, capability, supported, backend="auto") '
                      '-> None:\n'
                      '    """A CUDA device of `capability` on which only `supported` '
                      'kernels run."""\n'
                      '    monkeypatch.setattr(linear.current_platform, "_enum", '
                      'PlatformEnum.CUDA)\n'
                      '    monkeypatch.setattr(\n'
                      '        linear.current_platform,\n'
                      '        "get_device_capability",\n'
                      '        lambda device_id=0: DeviceCapability(*capability),\n'
                      '    )\n'
                      '    monkeypatch.setattr(linear, "_get_linear_backend", lambda: '
                      'backend)\n'
                      '    for kernel in _POSSIBLE_NVFP4_KERNELS[PlatformEnum.CUDA]:\n'
                      '        result = (True, None) if kernel in supported else '
                      '(False, "not here")\n'
                      '        monkeypatch.setattr(\n'
                      '            kernel,\n'
                      '            "is_supported",\n'
                      '            classmethod(lambda cls, compute_capability=None, '
                      'r=result: r),\n'
                      '        )\n'
                      '        monkeypatch.setattr(\n'
                      '            kernel, "can_implement", classmethod(lambda cls, '
                      'config: (True, None))\n'
                      '        )\n'
                      '\n'
                      '\n'
                      'def '
                      'test_a_gpu_without_native_fp4_refuses_instead_of_marlin(monkeypatch):\n'
                      '    # An H200: Marlin runs, as do FlashInfer kernels with no '
                      'capability check.\n'
                      '    device(\n'
