                      '    assert \'tool_choice "none"\' in str(refusal.value)\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("constraint,value", '
                      '_CHAT_CONSTRAINTS)\n'
                      'def '
                      'test_chat_keeps_the_constraint_when_no_tool_can_be_called(constraint, '
                      'value):\n'
                      '    request = _chat(tools=[_CHAT_TOOL], tool_choice="none", '
                      '**{constraint: value})\n'
                      '    assert request.extract_structured_outputs() is not None\n'
                      '    assert _chat(**{constraint: '
                      'value}).extract_structured_outputs() is not None\n'
                      '\n'
                      '\n'
                      'def test_chat_text_format_is_no_constraint():\n'
                      '    request = _chat(tools=[_CHAT_TOOL], '
