                      '    assert refusal.value.parameter == constraint\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("constraint,fields", '
                      '_RESPONSES_CONSTRAINTS)\n'
                      'def '
                      'test_responses_keeps_the_constraint_when_no_tool_can_be_called(constraint, '
                      'fields):\n'
                      '    request = _responses(tools=[_RESPONSES_TOOL], '
                      'tool_choice="none", **fields)\n'
                      '    assert request.extract_structured_outputs() is not None\n'
                      '    assert _responses(**fields).extract_structured_outputs() is '
