                      '\n'
                      'def '
                      'test_batch_invariance_does_not_substitute_emulation(monkeypatch):\n'
                      "    # VLLM_BATCH_INVARIANT's deterministic path is the native "
                      'CUTLASS kernel; on\n'
                      '    # a GPU without it, emulation is a substitute like any '
                      'other.\n'
                      '    monkeypatch.setenv("VLLM_BATCH_INVARIANT", "1")\n'
                      '    device(monkeypatch, (9, 0), {MarlinNvFp4LinearKernel, '
                      'EmulationNvFp4LinearKernel})\n'
                      '    with pytest.raises(ValueError, match="VLLM_BATCH_INVARIANT '
                      'needs") as refusal:\n'
                      '        init_nvfp4_linear_kernel()\n'
                      '    message = str(refusal.value)\n'
                      '    assert "compute capability 9.0" in message\n'
                      '    assert "CutlassNvFp4LinearKernel: not here" in message\n'
                      '    assert "EmulationNvFp4LinearKernel, does not compute in '
                      'FP4" in message\n'
                      '    assert "unset VLLM_BATCH_INVARIANT" in message\n'
                      '\n'
                      '\n'
                      'def test_batch_invariance_serves_named_emulation(monkeypatch):\n'
                      '    monkeypatch.setenv("VLLM_BATCH_INVARIANT", "1")\n'
                      '    device(monkeypatch, (9, 0), {EmulationNvFp4LinearKernel}, '
                      'backend="emulation")\n'
                      '    assert isinstance(init_nvfp4_linear_kernel(), '
                      'EmulationNvFp4LinearKernel)\n'
                      '\n'
                      '\n'
                      'def '
                      'test_batch_invariance_uses_cutlass_where_it_runs(monkeypatch):\n'
                      '    monkeypatch.setenv("VLLM_BATCH_INVARIANT", "1")\n'
