                             '        (NIXL, {"remote_engine_id": ["e"]}, "a '
                             'string"),\n'
                             '        (NIXL, {"remote_block_ids": []},\n'
                             '         "a non-empty list of lists of integers, one per '
                             'KV cache group or null"),\n'
