                      'def _stateless_serving(*, enable_store, model_type="test", '
                      '**launch):\n'
                      '    engine_client = MagicMock()\n'
                      '    engine_client.errored = False\n'
                      '    engine_client.model_config.max_model_len = 100\n'
                      '    engine_client.model_config.hf_config.model_type = '
                      'model_type\n'
                      '    '
                      'engine_client.model_config.get_diff_sampling_param.return_value '
                      '= {}\n'
                      '    serving = OpenAIServingResponses(\n'
                      '        engine_client=engine_client,\n'
                      '        models=MagicMock(),\n'
                      '        online_renderer=MagicMock(),\n'
                      '        request_logger=None,\n'
                      '        chat_template=None,\n'
                      '        chat_template_content_format="auto",\n'
                      '        **launch,\n'
                      '    )\n'
                      '    serving._check_model = AsyncMock(return_value=None)\n'
                      '    serving.enable_store = enable_store\n'
                      '    return serving, engine_client\n'
                      '\n'
                      '\n'
                      '@pytest.mark.asyncio\n'
                      'async def '
                      'test_previous_response_id_on_a_server_that_stores_nothing_is_refused():\n'
                      '    serving, engine = _stateless_serving(enable_store=False)\n'
                      '    request = ResponsesRequest(\n'
                      '        input="q", kv_scope="agent", '
                      'previous_response_id="resp_unknown"\n'
                      '    )\n'
                      '    refused = await serving.create_responses(request)\n'
                      '    assert isinstance(refused, ErrorResponse)\n'
                      '    assert (refused.error.code, refused.error.param) == (400, '
                      '"previous_response_id")\n'
                      '    assert "stores no responses" in refused.error.message\n'
                      '    assert "`input`" in refused.error.message\n'
                      '    assert "VLLM_ENABLE_RESPONSES_API_STORE=1" in '
                      'refused.error.message\n'
                      '    engine.admit.assert_not_called()\n'
                      '\n'
                      '    missing = await serving.retrieve_responses("resp_unknown", '
                      'None, False)\n'
                      '    assert (missing.error.code, missing.error.param) == (404, '
                      '"response_id")\n'
                      '    assert "stores no responses" in missing.error.message\n'
                      '\n'
                      '\n'
                      '@pytest.mark.asyncio\n'
                      'async def '
                      'test_an_unknown_previous_response_id_is_named_by_its_field():\n'
                      '    serving, engine = _stateless_serving(enable_store=True)\n'
                      '    request = ResponsesRequest(\n'
                      '        input="q", kv_scope="agent", '
                      'previous_response_id="resp_unknown"\n'
                      '    )\n'
                      '    assert serving._validate_create_responses_input(request) is '
                      'None\n'
                      '    missing = await serving.create_responses(request)\n'
                      '    assert (missing.error.code, missing.error.param) == (404, '
                      '"previous_response_id")\n'
                      '    assert missing.error.message == "Response with id '
                      '\'resp_unknown\' not found."\n'
                      '    engine.admit.assert_not_called()\n'
                      '\n'
                      '\n'
                      '@pytest.mark.asyncio\n'
                      '@pytest.mark.parametrize("runs_the_tool", [True, False])\n'
                      'async def '
                      'test_max_tool_calls_is_refused_where_built_in_calls_are_not_counted(\n'
                      '    runs_the_tool,\n'
                      '):\n'
                      '    # max_tool_calls bounds the built-in tool calls a response '
                      'processes; a\n'
                      '    # server that runs one itself does not count them.\n'
                      '    tool_server = MagicMock(spec=ToolServer)\n'
                      '    tool_server.has_tool.return_value = runs_the_tool\n'
                      '    serving, engine = _stateless_serving(\n'
                      '        enable_store=False,\n'
                      '        model_type="gpt_oss",\n'
                      '        reasoning_parser="openai_gptoss",\n'
                      '        tool_server=tool_server,\n'
                      '    )\n'
                      '    serving._make_request_with_harmony = MagicMock(\n'
                      '        return_value=([], [tokens_input([1, 2, 3])])\n'
                      '    )\n'
                      '    engine.admit = '
                      'AsyncMock(side_effect=RuntimeError("admitted"))\n'
                      '    request = ResponsesRequest(\n'
                      '        input="q",\n'
                      '        kv_scope="agent",\n'
                      '        max_tool_calls=1,\n'
                      '        tools=[{"type": "web_search_preview"}],\n'
                      '    )\n'
                      '    if runs_the_tool:\n'
                      '        with pytest.raises(VLLMValidationError) as refused:\n'
                      '            await serving.create_responses(request)\n'
                      '        assert refused.value.parameter == "max_tool_calls"\n'
                      '        assert "Omit max_tool_calls" in str(refused.value)\n'
                      '        engine.admit.assert_not_called()\n'
                      '    else:\n'
                      '        with pytest.raises(RuntimeError, match="admitted"):\n'
                      '            await serving.create_responses(request)\n'
                      '\n'
                      '\n'
                      '@pytest.mark.asyncio\n'
                      'async def '
                      'test_store_sent_true_on_a_server_that_stores_nothing_is_refused():\n'
                      '    serving, engine = _stateless_serving(enable_store=False)\n'
                      '    refused = await serving.create_responses(\n'
