                      '            SimpleNamespace(_executor=None, tokenizer=None),\n'
                      '            '
                      'mm_registry=SimpleNamespace(supports_multimodal_inputs=lambda '
                      '_: False),\n'
                      '        )\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("priority", [1, -1, 2**63 - 1])\n'
                      'def '
                      'test_a_priority_first_come_first_served_would_not_apply_is_refused(priority):\n'
                      '    with pytest.raises(VLLMValidationError) as refused:\n'
                      '        _admission("fcfs").process_inputs(\n'
                      '            "request",\n'
                      '            {"type": "token", "prompt_token_ids": [1]},\n'
                      '            SamplingParams(),\n'
                      '            ("generate",),\n'
                      '            priority=priority,\n'
                      '        )\n'
                      '    assert refused.value.parameter == "priority"\n'
                      '    assert refused.value.value == priority\n'
                      '    message = str(refused.value)\n'
                      '    assert "first come, first served (--scheduling-policy '
                      'fcfs)" in message\n'
                      '    assert "Send priority 0 or omit it" in message\n'
                      '    assert "--scheduling-policy priority" in message\n'
