                             '        "kv_scope": "unit",\n'
                             '    })\n'
                             '\n'
                             '\n'
                             'def _allowed(mode):\n'
                             '    return {"type": "allowed_tools", "mode": mode,\n'
                             '            "tools": [{"type": "function", "name": '
                             '"write"}]}\n'
                             '\n'
                             '\n'
                             '@pytest.mark.parametrize(\n'
                             '    ("request_", "held"),\n'
                             '    [\n'
                             '        (_chat("required"), True),\n'
                             '        (_chat(NAMED), True),\n'
                             '        (_responses("required"), True),\n'
                             '        (_responses({"type": "function", "name": '
                             '"write"}), True),\n'
                             '        (_responses(_allowed("required")), True),\n'
                             '        (_responses(_allowed("auto")), False),\n'
                             '        (_chat("auto"), False),\n'
                             '        (_chat("none"), False),\n'
                             '    ],\n'
                             ')\n'
                             'def '
                             'test_only_a_choice_whose_answer_is_calls_is_held_through_reasoning(\n'
                             '    request_, held\n'
