                             '    request.structured_output_request.grammar = '
                             'manager._create_grammar(request)\n'
                             '    return engine_request, request, manager\n'
                             '\n'
                             '\n'
                             'def _walk(manager, request, ids, watched):\n'
                             '    """Step *ids* as the scheduler does, one token per '
                             'step: for each, whether\n'
                             '    the mask was applied and which of *watched* and the '
                             'token it allowed.\n'
                             '    Stops at the first token the mask forbids."""\n'
                             '    grammar = request.structured_output_request.grammar\n'
                             '    bitmask = manager.backend.allocate_token_bitmask(1)\n'
                             '    steps = []\n'
                             '    for token in ids:\n'
                             '        masked = manager.should_fill_bitmask(request)\n'
                             '        allowed = {}\n'
                             '        if masked:\n'
                             '            grammar.fill_bitmask(bitmask, 0)\n'
                             '            for checked in (*watched, token):\n'
                             '                word = int(bitmask[0][checked // '
                             '32].item()) & 0xFFFFFFFF\n'
                             '                allowed[checked] = bool(word & (1 << '
                             '(checked % 32)))\n'
                             '        steps.append((masked, allowed))\n'
                             '        if masked and not allowed[token]:\n'
                             '            break\n'
                             '        request.append_output_token_ids(token)\n'
                             '        if manager.should_advance(request, '
                             'new_token_ids=[token]):\n'
                             '            advance = '
                             'manager.trim_reasoning_for_advance(request, [token])\n'
                             '            assert '
                             'grammar.accept_tokens(request.request_id, advance)\n'
                             '    return steps\n'
                             '\n'
                             '\n'
                             '@pytest.mark.parametrize("choice", ["required", NAMED], '
                             'ids=["required", "named"])\n'
                             'def '
                             'test_the_engine_holds_it_from_the_first_generated_token(served, '
                             'choice):\n'
                             '    tokenizer, eos = served\n'
                             '    prompt = _encode(tokenizer, OPEN)\n'
                             '    held = _armed(tokenizer, _chat(choice), prompt)\n'
                             '    think_end, tool_call = (\n'
                             '        tokenizer.convert_tokens_to_ids(marker) for '
                             'marker in ("</think>", "<tool_call>")\n'
                             '    )\n'
                             '    reasoning = _encode(tokenizer, "I read the files, so '
                             'I will record it.")\n'
                             '    answer = [think_end] + _encode(tokenizer, "\\n\\n" + '
                             'CALL)\n'
                             '\n'
                             '    _, request, manager = _engine(tokenizer, eos, held, '
                             'prompt)\n'
                             '    steps = _walk(manager, request, reasoning + answer + '
                             '[eos[0]],\n'
                             '                  (*eos, tool_call, think_end))\n'
                             '    assert len(steps) == len(reasoning) + len(answer) + '
                             '1\n'
                             '    assert all(masked for masked, _ in steps)\n'
                             '    assert all(allowed[token] for token, (_, allowed) in '
                             'zip(\n'
                             '        reasoning + answer + [eos[0]], steps))\n'
                             '    # EOS is refused until the call is complete, '
                             'reasoning included; the\n'
                             "    # closer -- a thinking budget's forced one too -- "
                             'may come at every\n'
