                      '\n'
                      'def test_the_qwen_format_is_served_as_one_engine():\n'
                      '    """A reasoning parser and a tool parser that both adapt the '
                      'Qwen engine\n'
                      '    are served as that one engine, which parses the output in '
                      'one pass; the\n'
                      '    serving layer reads the two configured parsers from the '
                      'class, as it\n'
                      "    reads a composed parser's. Two engines, or a reasoning "
                      'parser served\n'
                      '    without a tool parser, stay composed."""\n'
                      '    from itertools import product\n'
                      '\n'
                      '    from vllm.parser.abstract_parser import DelegatingParser\n'
                      '    from vllm.parser.parser_manager import ParserManager\n'
                      '    from vllm.parser.qwen3 import Qwen3ServedParser\n'
                      '    from vllm.reasoning import ReasoningParserManager\n'
                      '    from vllm.tool_parsers import ToolParserManager\n'
                      '\n'
                      '    tokenizer = make_mock_tokenizer({TOOL_CALL_START: 100, '
                      'TOOL_CALL_END: 101})\n'
                      '    for reasoning, tool in product(("qwen3", "mimo"), '
                      '("qwen3_coder", "qwen3_xml", "mimo")):\n'
                      '        served = ParserManager.get_parser(\n'
                      '            tool_parser_name=tool, '
                      'reasoning_parser_name=reasoning,\n'
                      '            enable_auto_tools=True,\n'
                      '        )\n'
                      '        assert issubclass(served, Qwen3ServedParser), '
                      '(reasoning, tool)\n'
                      '        assert not issubclass(served, DelegatingParser)\n'
                      '        assert served.reasoning_parser_cls is (\n'
                      '            '
                      'ReasoningParserManager.get_reasoning_parser(reasoning)\n'
                      '        )\n'
                      '        assert served.tool_parser_cls is '
                      'ToolParserManager.get_tool_parser(tool)\n'
                      '        parser = served(tokenizer, [])\n'
                      '        assert parser.reasoning_parser is None\n'
                      '        assert parser.tool_parser is None\n'
                      '    for reasoning, tool, auto in (\n'
                      '        ("nemotron_v3", "qwen3_coder", True),\n'
                      '        ("qwen3", "qwen3_coder", False),\n'
                      '    ):\n'
                      '        composed = ParserManager.get_parser(\n'
                      '            tool_parser_name=tool, '
                      'reasoning_parser_name=reasoning,\n'
                      '            enable_auto_tools=auto,\n'
                      '        )\n'
                      '        assert issubclass(composed, DelegatingParser), '
                      '(reasoning, tool, auto)\n'
                      '\n'
                      '\n'
                      '@pytest.mark.parametrize("thinking", [True, False])\n'
                      'def '
                      'test_the_one_engine_arms_the_grammar_a_composition_arms(thinking):\n'
                      '    """The served engine arms the grammar a composition of the '
                      'same two\n'
                      '    parsers arms, for every tool choice and wherever the prompt '
                      'leaves\n'
                      '    reasoning: one function decides what the grammar covers and '
                      'where the\n'
                      "    engine applies it, so the request's structured-output "
                      'parameters --\n'
                      '    ``enable_in_reasoning`` among them -- are the same."""\n'
                      '    import copy\n'
                      '\n'
                      '    from vllm.entrypoints.openai.chat_completion.protocol '
                      'import (\n'
                      '        ChatCompletionRequest,\n'
                      '    )\n'
                      '    from vllm.entrypoints.openai.responses.protocol import '
                      'ResponsesRequest\n'
                      '    from vllm.parser.abstract_parser import DelegatingParser\n'
                      '    from vllm.parser.parser_manager import ParserManager\n'
                      '\n'
                      '    served = ParserManager.get_parser(\n'
                      '        tool_parser_name="qwen3_coder", '
                      'reasoning_parser_name="qwen3",\n'
                      '        enable_auto_tools=True,\n'
                      '    )\n'
                      '    composed = type("Composed", (DelegatingParser,), {\n'
                      '        "reasoning_parser_cls": served.reasoning_parser_cls,\n'
                      '        "tool_parser_cls": served.tool_parser_cls,\n'
                      '    })\n'
                      '    think, think_end, text = 50, 51, 7\n'
                      '    tokenizer = make_mock_tokenizer({\n'
                      '        "<think>": think, "</think>": think_end,\n'
                      '        TOOL_CALL_START: 100, TOOL_CALL_END: 101,\n'
                      '    })\n'
                      '    parameters = {\n'
                      '        "type": "object", "properties": {"text": {"type": '
                      '"string"}},\n'
                      '        "required": ["text"], "additionalProperties": False,\n'
                      '    }\n'
                      '    tool = {"type": "function", "function": {"name": "write", '
                      '"parameters": parameters}}\n'
                      '    function = {"type": "function", "name": "write", '
                      '"parameters": parameters}\n'
                      '\n'
                      '    def chat(**fields):\n'
                      '        return ChatCompletionRequest(model="m", messages=[], '
                      'tools=[tool], **fields)\n'
                      '\n'
                      '    def responses(choice):\n'
                      '        return ResponsesRequest.model_validate({\n'
                      '            "model": "m", "input": "x", "tools": [function], '
                      '"tool_choice": choice,\n'
                      '            "kv_scope": "unit",\n'
                      '        })\n'
                      '\n'
                      '    def allowed(mode):\n'
                      '        return {"type": "allowed_tools", "mode": mode,\n'
                      '                "tools": [{"type": "function", "name": '
                      '"write"}]}\n'
                      '\n'
                      '    named = {"type": "function", "function": {"name": '
                      '"write"}}\n'
                      '    requests = [\n'
                      '        chat(tool_choice="auto"), chat(tool_choice="none"),\n'
                      '        chat(tool_choice="required"), chat(tool_choice=named),\n'
                      '        chat(tool_choice="required", '
                      'parallel_tool_calls=False),\n'
                      '        chat(tool_choice="auto", parallel_tool_calls=False),\n'
                      '        ChatCompletionRequest(model="m", messages=[]),\n'
                      '        responses("required"), responses({"type": "function", '
                      '"name": "write"}),\n'
                      '        responses(allowed("required")), '
                      'responses(allowed("auto")),\n'
                      '        responses("none"),\n'
                      '    ]\n'
                      '    prompts = [\n'
                      '        # The served generation prompt ends inside the <think> '
                      'it wrote.\n'
                      '        [text, think, text],\n'
                      '        # A continued final message closed reasoning.\n'
                      '        [think, text, think_end, text],\n'
                      '        # A call the prompt opened after its reasoning ends '
                      'that reasoning.\n'
                      '        [think, text, 100, text],\n'
                      '        # A template that leaves the opener to the model.\n'
                      '        [text],\n'
                      '        # No rendered prompt.\n'
                      '        None,\n'
                      '    ]\n'
                      '    kwargs = {"chat_template_kwargs": {"enable_thinking": '
                      'thinking}}\n'
                      '    held = 0\n'
                      '    for request in requests:\n'
                      '        for prompt in prompts:\n'
                      '            armed = [\n'
                      '                parser_cls(tokenizer, request.tools, '
                      '**kwargs).adjust_request(\n'
                      '                    copy.deepcopy(request), '
                      'prompt_token_ids=prompt\n'
                      '                )\n'
                      '                for parser_cls in (composed, served)\n'
                      '            ]\n'
                      '            dumps = [(\n'
                      '                adjusted.skip_special_tokens,\n'
                      '                adjusted.structured_outputs,\n'
                      '                getattr(adjusted, "response_format", None),\n'
                      '                getattr(adjusted, "text", None),\n'
                      '            ) for adjusted in armed]\n'
                      '            assert dumps[0] == dumps[1], (request.tool_choice, '
                      'prompt)\n'
                      '            outputs = armed[1].structured_outputs\n'
                      '            held += bool(outputs is not None and '
                      'outputs.enable_in_reasoning)\n'
                      '    # The forced choices are held through reasoning exactly '
                      'where the\n'
                      '    # prompt left it open while the model thinks.\n'
                      '    assert held == (6 if thinking else 0)\n',
